TN.defSec("environmental",{"nonfreezing-cold-injury":{"id":"nonfreezing-cold-injury","variants":[{"id":"nonfreezing-cold-main","o":{"L":[{"t":"(none specific; add CBC / glucose if systemically unwell)"}],"T":[{"t":"Drying, elevation, warming, and bandaging of the affected body part"},{"t":"Chilblains: nifedipine 20 mg PO three times daily, or pentoxifylline 400 mg PO three times daily, or limaprost 20 µg PO three times daily; topical corticosteroid (e.g., 0.025% fluocinolone cream)"}],"Co":[{"t":"Discharge with follow-up; surgical / vascular consult if necrosis or non-viable tissue"}]},"name":"Trench foot / chilblains","level":"III","imp":"Nonfreezing cold injury (trench foot / chilblains)","cond":"Urgent","act":"CBR","diet":"PO","ecg":"none","cxr":"none","sc":"مردی بی‌خانمان با پای سرد، رنگ‌پریده و بی‌حس پس از روزها پوشیدن جوراب خیس؛ یا زنی با ندول‌های آبی دردناک انگشتان دست.","why":"خشک و گرم کردن؛ chilblains دارودرمانی."}],"ch":"118","name":"Nonfreezing cold injury (trench foot, chilblains / pernio)","name_fa":"سرمازدگی بدون انجماد (trench foot و chilblains)","cc":["environmental","joint-limb-pain","rash"],"keywords":"trench foot, chilblains, pernio, nonfreezing cold injury, nifedipine, pentoxifylline, سرمازدگی, پای سنگر","status":"draft","features":["trench foot: آسیب مستقیم بافت نرم ناشی از مواجهه طولانی با سرما و رطوبت بدون انجماد؛ پا ابتدا رنگ‌پریده، لکه‌دار، بدون نبض و بی‌حس و با گرم کردن سریع بهتر نمی‌شود؛ چند ساعت بعد از گرم کردن (2 تا 3 روز) هیپرمیک و دردناک با برگشت پرفیوژن؛ تاول و ادم دیررس؛ بی‌حسی ممکن است هفته‌ها یا دائمی؛ هیپرهیدروز و حساسیت به سرما ماه‌ها تا سال‌ها","chilblains (pernio): ضایعات التهابی دردناک گوش، دست و پا از مواجهه مزمن متناوب با شرایط مرطوب بدون انجماد؛ ادم موضعی، اریتم و سیانوز تا 12 ساعت بعد، با خارش و پارستزی سوزشی؛ ندول‌های آبی دردناک پس از گرم شدن تا چند روز"],"ddx":[{"n":"Frostbite |","cm":1},{"n":"Acute limb ischemia |","cm":1},{"n":"Raynaud phenomenon / vasculitis |"}],"redflags":["پای بدون نبض و بی‌حس، گانگرن، تاول"],"guide":"trench foot و chilblains: خشک کردن، بالا نگه داشتن، گرم کردن و پانسمان. chilblains: افزودن nifedipine 20 mg PO سه بار در روز، pentoxifylline 400 mg PO سه بار در روز یا limaprost 20 µg PO سه بار در روز، و کورتیکواستروئید موضعی مثل fluocinolone 0.025%.","section":"environmental","source":"Tintinalli's Emergency Medicine Manual, 8th ed., Ch. 118: Cold Injuries, pp. 649–654"},"frostbite":{"id":"frostbite","variants":[{"id":"frostbite-superficial","o":{"L":[{"t":"(none required; laboratory testing and imaging not needed to diagnose frostbite)"}],"S":[{"t":"IV access if needed for analgesia"}],"T":[{"t":"Rapid rewarming in circulating water at 37–39°C (98.6–102.2°F) for 20–30 min until tissue pliable and erythematous"},{"t":"Topical aloe vera every 6 h"},{"t":"Analgesia (parenteral opioids initially, then oral NSAIDs); local wound care and dressing; splint and elevate"},{"t":"Tetanus immunoprophylaxis if needed","fl":[{"k":"note","v":"debridement of clear blisters / aspiration of hemorrhagic blisters controversial; prophylactic bacitracin, antibiotics, silver sulfadiazine controversial"}]}],"Co":[{"t":"Discharge home with close follow-up for superficial local frostbite"}]},"name":"Superficial frostbite (frostnip / first-second degree)","level":"III","imp":"Frostbite, superficial","cond":"Urgent","act":"CBR","diet":"PO","ecg":"none","cxr":"none","sc":"اسکی‌باز با سفیدی و بی‌حسی نوک انگشتان که پس از گرم شدن اریتماتو و دردناک شد، تاول شفاف.","why":"گرم کردن با آب 37 تا 39 درجه، aloe vera و ترخیص با پیگیری."},{"id":"frostbite-deep","o":{"L":[{"t":"CBC, electrolytes, glucose (if systemically ill / hypothermic)"}],"S":[{"t":"IV access for parenteral analgesia"}],"T":[{"t":"Rapid rewarming in circulating water at 37–39°C for 20–30 min"},{"t":"Topical aloe vera every 6 h; analgesia (parenteral opioids initially, then oral NSAIDs); splint and elevate; dressing"},{"t":"Tetanus immunoprophylaxis if needed"}],"Co":[{"t":"Admit for ongoing care; surgical consultation (blister management, local preference)"}]},"name":"Deep frostbite (third–fourth degree, hemorrhagic bullae, nonblanching cyanosis)","level":"II","imp":"Frostbite, deep","cond":"Urgent","act":"CBR","diet":"PO","ecg":"once","cxr":"none","sc":"کوهنورد با انگشتان سیاه، تاول هموراژیک و سیانوز مقاوم پس از گرم کردن.","why":"گرم کردن، مسکن و بستری؛ مشاوره جراحی."}],"ch":"118","name":"Frostbite","name_fa":"سرمازدگی انجمادی (Frostbite)","cc":["environmental","joint-limb-pain","limb-injury"],"keywords":"frostbite, frostnip, rewarming, hemorrhagic bullae, aloe vera, tetanus, یخ زدگی","status":"draft","features":["انجماد بافت؛ ابتدا سوزش، گزگز و بی‌حسی؛ درجه‌بندی بر اساس ظاهر پس از گرم کردن: درجه 1 (frostnip): انجماد بخشی ضخامت پوست، اریتم، ادم، بدون تاول و بدون از دست رفتن بافت؛ درجه 2: انجماد تمام‌ضخامت پوست، تاول شفاف، بی‌حسی سپس درد زونکی؛ درجه 3: انجماد پوست و شبکه زیرجلدی، تاول هموراژیک و نکروز پوست؛ درجه 4: تا عضله، تاندون و استخوان با پوست لکه‌دار، سیانوز غیرقابل رنگ‌پریدگی و بالاخره escar خشک سیاه مومیایی","در ابتدا بهتر است سطحی یا عمیق دسته‌بندی شود؛ آزمایش و تصویربرداری برای تشخیص لازم نیست"],"ddx":[{"n":"Hypothermia (concurrent) |","cm":1},{"n":"Chilblains / trench foot |"},{"n":"Acute arterial occlusion |"}],"redflags":["تاول هموراژیک، پوست سیاه، سیانوز نایل‌بلانش، هیپوترمی همزمان"],"guide":"گرم کردن سریع در آب در گردش 37 تا 39 درجه سانتی‌گراد (98.6 تا 102.2 F) به مدت 20 تا 30 دقیقه تا نرم و اریتماتو شدن بافت. دبریدمان تاول شفاف و آسپیراسیون تاول هموراژیک بحث‌برانگیز: با جراح مشورت (ترجیح محلی). aloe vera موضعی هر 6 ساعت. مدیریت درد، مراقبت از زخم، پانسمان، آتل و بالا نگه داشتن؛ ممکن است اوپیوئید تزریقی ابتدا و سپس NSAID خوراکی. واکسیناسیون کزاز در صورت نیاز. سطحی موضعی: ترخیص با پیگیری نزدیک؛ عمیق‌تر: بستری. پروفیلاکسی با bacitracin، آنتی‌بیوتیک و silver sulfadiazine بحث‌برانگیز.","section":"environmental","source":"Tintinalli's Emergency Medicine Manual, 8th ed., Ch. 118: Cold Injuries, pp. 649–654"},"accidental-hypothermia":{"id":"accidental-hypothermia","variants":[{"id":"hypothermia-mild","o":{"L":[{"t":"Glucose (fingerstick); CBC, electrolytes, BUN, creatinine; TSH and random cortisol if secondary hypothermia suspected"}],"S":[{"t":"Warm IV fluid titrated to volume status if needed","fl":[{"k":"ci","v":"caution in heart failure / pulmonary edema"}]},{"t":"Dextrose 50 mL IV if hypoglycemia"}],"T":[{"t":"Warm environment and clothing; remove wet clothing, dry and cover; warm sweet drinks; active movement if possible"},{"t":"Continuous monitoring: vital signs, pulse oximetry, core temperature (rectal, bladder, or esophageal low-reading thermometer)"},{"t":"HT I with significant trauma, comorbidities, or suspected secondary hypothermia: treat as HT II"}],"Co":[{"t":"Discharge if hypothermia resolves quickly and social circumstances allow; admit if symptomatic or secondary"}]},"name":"Mild hypothermia, HT I (32–35°C, conscious, shivering)","level":"III","imp":"Accidental hypothermia, mild (HT I)","cond":"Urgent","act":"CBR","diet":"PO","ecg":"stat","cxr":"none","sc":"مرد جوان پس از شب سرد با لرز، هوشیار، دمای مرکزی 34°C.","why":"گرم کردن پاسیو، نوشیدنی شیرین گرم؛ علت زمینه‌ای را رد کن."},{"id":"hypothermia-moderate","o":{"I":[{"t":"CXR portable (aspiration)"},{"t":"Bedside ultrasonography to assess cardiovascular status"}],"L":[{"t":"Glucose, CBC, electrolytes (potassium), BUN, creatinine, TSH, random cortisol, clotting profile, lactate, lipase, blood gas (DIC / acid–base)"}],"S":[{"t":"Warmed IV fluids titrated to volume status","fl":[{"k":"ci","v":"caution in heart failure / pulmonary edema"}]},{"t":"Dextrose 50 mL IV for hypoglycemia"},{"t":"Hormone replacement if hypothyroidism / hypoadrenalism suspected"}],"T":[{"t":"Continuous cardiac monitoring, pulse oximetry, core temperature (rectal, bladder, or esophageal low-reading)"},{"t":"Warm environment; active external and minimally invasive rewarming (chemical, electrical, or forced air heating packs or blankets; warm parenteral fluids); full-body insulation, horizontal position; minimal and cautious movements"},{"t":"Airway management as required (intubation indications as normothermic)"},{"t":"Bradycardia, AF and flutter usually require no therapy; VF refractory until rewarmed (single defibrillation attempt per AHA)"},{"t":"Active core rewarming / extracorporeal rewarming (ECMO or CPB) for cardiovascular instability"}],"Co":[{"t":"Prefer treatment at ECMO/CPB center for HT III; consider ECMO for cardiac instability refractory to medical management or comorbid patients unlikely to tolerate low cardiac output"},{"t":"Admit ICU; toxicology if drug intoxication"}]},"name":"Moderate–severe hypothermia, HT II–III (< 32°C, impaired consciousness, bradycardia/AF)","level":"I","imp":"Accidental hypothermia, moderate to severe (HT II–III)","cond":"Emergent","act":"CBR","diet":"NPO","ecg":"stat","cxr":"portable","o2":"warmed humidified oxygen","sc":"مرد ۶۰ ساله یافت‌شده در برف با گیجی، لرز قطع، دمای مرکزی 29°C، HR 38 و موج Osborn.","why":"گرم کردن فعال خارجی/مینیمال تهاجمی، جابه‌جایی آرام و ECMO در ناپایداری."},{"id":"hypothermia-arrest","o":{"L":[{"t":"Core temperature; serum potassium (< 12 mmol/L required before ECMO/CPB consideration); glucose, electrolytes, blood gas"}],"T":[{"t":"CPR (palpate pulse / respirations 30–45 s first; or bedside ultrasonography); airway management; up to three doses of epinephrine and defibrillation (further dosing guided by clinical response)"},{"t":"Prevent further heat loss (insulation, warm environment); do not apply heat to head"},{"t":"Active external and minimally invasive rewarming during transport (recommended but controversial)"},{"t":"If ECMO not available within a few hours (6 h): on-site rewarming with hot packs / forced air blankets, warm IV fluid, ± warm thoracic, bladder, peritoneal lavage"},{"t":"Do NOT terminate CPR until rewarmed to ≥ 32°C unless obvious irreversible death, valid DNR, unsafe conditions, avalanche burial > 35 min with packed airway, or serum K ≥ 12"}],"Co":[{"t":"Transport to ECMO/CPB center (may reduce mortality by 40–90%); post-arrest management and targeted temperature management after ROSC"}]},"name":"Hypothermic cardiac arrest (HT IV, vital signs absent)","level":"I","imp":"Accidental hypothermia, cardiac arrest (HT IV)","cond":"Emergent","act":"CBR","diet":"NPO","ecg":"stat","cxr":"portable","sc":"مرد بی‌خانمان یافت‌شده بدون نبض و تنفس، دمای مرکزی 24°C.","why":"CPR ادامه، انتقال به مرکز ECMO؛ CPR را قطع نکن."}],"ch":"118","name":"Accidental hypothermia","name_fa":"هیپوترمی تصادفی","cc":["environmental","altered-mental-status","hypotension-shock"],"keywords":"hypothermia, Osborn J wave, ECMO, rewarming, core temperature, cold diuresis, HT staging, هیپوترمی, موج اوسبورن","status":"draft","features":["دمای مرکزی < 35°C (< 95°F)؛ اتلاف حرارت با هدایت، همرفت، تابش یا تبخیر","طیف پیوسته: خفیف (32 تا 35°C): تاکی‌کاردی، تاکی‌پنه، هیپرتانسیون، لرز و هوشیاری طبیعی؛ زیر 32: لرز قطع، کاهش HR و BP؛ سپس گیجی، لتارژی، کما، از دست رفتن رفلکس مردمک، کاهش RR، کاهش رفلکس gag و سرفه، برونکوره؛ آسپیراسیون شایع؛ دیورز سرد و هموکونسانتراسیون","قلب: برادیکاردی سینوسی → AF با پاسخ بطنی آهسته → VF → آسیستول؛ زیر 32 خطر دیسریتمی؛ زیر 28°C خطر ایست قلبی و دیسریتمی بدخیم","تشخیص بر اساس دمای مرکزی؛ ممکن است بدون شرح حال مواجهه واضح نباشد؛ ترمومتر low-reading؛ آزمایش: گلوکز، CBC، الکترولیت، TSH، کورتیزول تصادفی، پروفایل انعقادی، لاکتات، لیپاز، کراتینین، گاز خون و ECG؛ اختلال اسید-باز الگوی قابل‌پیش‌بینی ندارد؛ ترومبوز داخل‌عروقی، آمبولی و DIC","ECG: طولانی شدن PR، QRS و QT، T وارونه، موج Osborn J","علل: مواجهه محیطی، هیپوگلیسمی، هیپوتیروئیدی، هیپوآدرنالیسم، هیپوپیتوئیتاریسم، اختلال CNS، مسمومیت دارویی، سپسیس، بیماری پوستی"],"ddx":[{"n":"Sepsis |","cm":1},{"n":"Hypoglycemia |","cm":1},{"n":"Hypothyroidism / adrenal insufficiency (myxedema, Addisonian crisis) |"},{"n":"Drug intoxication / CNS dysfunction |"}],"redflags":["دمای < 32°C، ناپایداری قلبی، بیهوشی، فشار < 90، آریتمی بطنی، دمای < 28°C"],"guide":"محیط گرم؛ پایش مداوم علائم حیاتی، پالس‌اکسیمتری و دمای مرکزی (رکتال، مثانه یا مری)؛ اندیکاسیون اینتوباسیون مثل نورموترمیک؛ مایع IV گرم شده با سرعت بر اساس حجم؛ لباس خیس خارج، خشک و پوشاندن. جابه‌جایی آرام برای جلوگیری از دیسریتمی کشنده. نبض و تنفس 30 تا 45 ثانیه؛ اگر نبود CPR؛ یا سونوگرافی بالین. برادیکاردی سینوسی، AF، فلوتر معمولاً درمان لازم ندارد و با گرم شدن برطرف؛ VF مقاوم تا گرم شدن (AHA یک تلاش شوک). روش‌های گرم کردن (جدول 118-1): پاسیو، فعال خارجی، فعال مرکزی؛ انتخاب بر اساس وضعیت قلبی-عروقی. پایدار و دمای > 30°C: پاسیو. ناپایدار: گرم کردن مرکزی سریع؛ extracorporeal (ECMO/CPB) انتخاب شده. ادامه احیا تا دمای 32°C. علت زمینه‌ای: دکستروز 50 mL IV در هیپوگلیسمی؛ جایگزینی هورمون در هیپوتیروئیدی/هیپوآدرنالیسم. بستری: همه علامت‌دار یا ثانویه؛ سالم با هیپوترمی خفیف محیطی که سریع رفع شد: ترخیص اگر شرایط اجتماعی اجازه دهد.","section":"environmental","source":"Tintinalli's Emergency Medicine Manual, 8th ed., Ch. 118: Cold Injuries, pp. 649–654"},"heat-stroke":{"id":"heat-stroke","variants":[{"id":"heat-stroke-main","o":{"I":[{"t":"CXR portable"},{"t":"CT head / neuroimaging as clinically indicated"}],"L":[{"t":"Electrolytes (hourly initially), BUN, creatinine, glucose, phosphate, calcium, liver enzymes, CBC, PT/INR (DIC), CPK and myoglobin, urinalysis, blood gas; toxicology screen and septic workup as indicated"}],"S":[{"t":"IV crystalloid to maintain MAP above 80–90 mmHg","fl":[{"k":"ci","v":"avoid volume overload; caution in heart failure / pulmonary edema"}]},{"t":"IV hydration for rhabdomyolysis","fl":[{"k":"ci","v":"no proven benefit of urine alkalinization or forced diuresis with mannitol / loop diuretics"}]}],"T":[{"t":"Continuous monitoring: vital signs and core temperature (rectal, bladder, esophageal); high-flow oxygen; intubate if significantly altered mental status, diminished gag, or hypoxia"},{"t":"Rapid cooling until core temperature 38°C (100.4°F): evaporative cooling (wet skin + fan), cooling blanket, ice packs to groin / axillae / neck; cold water immersion if practical; internal cooling (room temperature IV fluid, central heat exchange catheter) in severe cases; CPB in extreme cases","fl":[{"k":"ci","v":"antipyretics (acetaminophen, ibuprofen) and dantrolene are ineffective"}]},{"t":"Lorazepam 1–2 mg IV or diazepam 5 mg IV for seizures / excessive shivering"},{"t":"Vasopressors if required; treat hyperkalemia and DIC with standard regimens"}],"Co":[{"t":"ICU admission"}]},"name":"Heat stroke (core temperature > 40°C with CNS dysfunction)","level":"I","imp":"Heat stroke","cond":"Emergent","act":"CBR","diet":"NPO","ecg":"stat","cxr":"portable","o2":"high-flow oxygen","sc":"دونده ۲۵ ساله ماراتن در گرما با گیجی، دمای رکتال 41.5°C، تاکی‌کاردی و تشنج.","why":"خنک‌سازی تبخیری فوری تا 38°C؛ بدون ضدتب."}],"ch":"119","name":"Heat stroke (exertional and nonexertional)","name_fa":"گرمازدگی (Heat stroke)","cc":["environmental","altered-mental-status","fever"],"keywords":"heat stroke, exertional heat stroke, hyperthermia, evaporative cooling, rhabdomyolysis, DIC, گرمازدگی, هیپرترمی","status":"draft","features":["هیپرترمی (دمای مرکزی > 40°C / 104°F) + آسیب ارگان انتهایی؛ ارتفاع دما و مدت مواجهه شدت آسیب را تعیین می‌کند؛ بافت عصبی، هپاتوسیت‌ها، نفرون‌ها و اندوتلیوم عروقی حساس‌ترین","نورولوژیک: گیجی، آژیتاسیون، رفتار عجیب، آتاکسی، تشنج و کما؛ هیپرونتیلاسیون، استفراغ، اسهال، الیگوری؛ آنهیدروز یا تعریق شدید؛ کوآگولوپاتی/DIC: پورپورا، هموپتیزی، خونریزی GI","اگزرشنال: فعالیت فیزیکی در گرما/رطوبت؛ تبخیر مکانیسم اصلی اتلاف حرارت ولی با رطوبت > 75% بی‌اثر؛ غیراگزرشنال: ناتوان، بیمار مزمن و کسانی که نمی‌توانند از محیط گرم بگریزند (ماشین بسته، نوزاد بسیار پوشیده، خانه گرم)","یافته‌های زودرس آزمایشگاه: هیپوگلیسمی، هیپوفسفاتمی، هیپوکالمی، افزایش آنزیم کبد، هیپرکلسمی، هماتوکریت بالا، CPK و میوگلوبین (رابدومیولیز)؛ DIC و نارسایی کلیه با گذشت زمان"],"ddx":[{"n":"Sepsis / meningitis / encephalitis / malaria / tetanus |","cm":1},{"n":"Thyroid storm / DKA |","cm":1},{"n":"Toxic: sympathomimetics, anticholinergics, salicylates, serotonin syndrome, NMS, malignant hyperthermia, alcohol / benzodiazepine withdrawal |"},{"n":"Stroke / status epilepticus |"}],"redflags":["دمای > 40°C، تغییر هوشیاری، تشنج، کوآگولوپاتی، الیگوری، CPK بالا"],"guide":"شناسایی دقیق هیپرترمی با آسیب ارگان و کاهش سریع عدم تعادل حرارتی. ABC؛ اینتوباسیون در تغییر هوشیاری قابل‌توجه، کاهش gag یا هیپوکسی. پایش مداوم علائم حیاتی و دمای مرکزی (رکتال، مثانه یا مری)؛ اکسیژن پرجریان؛ کریستالوئید IV برای MAP > 80 تا 90 mmHg؛ از اضافه‌بار حجم بپرهیز؛ ممکن است وازوپرسور. خنک‌سازی سریع تا 38°C: خارجی مؤثرترین: پتوی خنک، خیس کردن پوست و فن (تبخیری)، یخ در کشاله ران/زیربغل/گردن؛ غوطه‌وری در آب سرد مؤثر ولی عملی نیست؛ داخلی: مایع IV دمای اتاق، کاتتر مرکزی تبادل حرارت و در شدید cardiopulmonary bypass؛ lavage معده، رکتوم و مثانه برتر از خارجی نیست (جدول 119-1). تشنج و لرز زیاد: بنزودیازپین (lorazepam 1 تا 2 mg IV یا diazepam 5 mg IV). رابدومیولیز: هیدراتاسیون IV (قلیایی‌سازی ادرار یا دیورز اجباری با mannitol یا دیورتیک لوپ بهبود پیامد ثابت نکرده). الکترولیت هر ساعت در ابتدا؛ هیپرکالمی و DIC با رژیم استاندارد. ضدتب (acetaminophen، ibuprofen) و dantrolene بی‌اثر و نباید استفاده شوند. اغلب بستری ICU.","section":"environmental","source":"Tintinalli's Emergency Medicine Manual, 8th ed., Ch. 119: Heat Emergencies, pp. 655–657"},"minor-heat-illness":{"id":"minor-heat-illness","variants":[{"id":"heat-syncope-cramps","o":{"L":[{"t":"Electrolytes, BUN, creatinine, glucose; CPK if severe cramps"}],"S":[{"t":"Oral or IV rehydration ; (isotonic fluid) for volume depletion","fl":[{"k":"ci","v":"caution in heart failure / CKD"}]}],"T":[{"t":"Rest; oral or IV rehydration (replace salt as well as free water)"}],"Co":[{"t":"Discharge home; exclude other causes of syncope"}]},"name":"Heat syncope / heat cramps","level":"III","imp":"Minor heat illness (heat syncope / heat cramps)","cond":"Urgent","act":"CBR","diet":"PO","ecg":"stat","cxr":"none","sc":"ورزشکار ۲۰ ساله با گرفتگی دردناک ساق پس از بازی در گرما؛ یا سالمند با سنکوپ در هوای گرم.","why":"هیدراتاسیون با نمک؛ ECG برای رد علل سنکوپ."},{"id":"heat-edema-rash","o":{"T":[{"t":"Heat edema: elevation of extremities or compressive stockings","fl":[{"k":"ci","v":"avoid diuretics (exacerbate volume depletion)"}]},{"t":"Heat rash: antihistamines, low-potency topical corticosteroids, or calamine lotion; light, loose-fitting clothing"}],"Co":[{"t":"Discharge home"}]},"name":"Heat edema / heat rash","level":"III","imp":"Minor heat illness (heat edema / heat rash)","cond":"Urgent","act":"CBR","diet":"PO","ecg":"none","cxr":"none","sc":"گردشگر با تورم دست و پا و راش زیر لباس در روزهای اول سفر گرم.","why":"خودمحدود؛ بالا نگه داشتن و آنتی‌هیستامین."}],"ch":"119","name":"Minor heat illness (heat syncope, cramps, edema, rash)","name_fa":"بیماری‌های خفیف گرما (سنکوپ، گرفتگی، ادم، راش)","cc":["environmental","syncope","joint-limb-pain","rash"],"keywords":"heat syncope, heat cramps, heat edema, heat rash, prickly heat, گرمازدگی خفیف, گرفتگی عضلانی, سنکوپ گرمایی","status":"draft","features":["سنکوپ گرمایی: کمبود حجم، اتساع عروق محیطی و کاهش تون وازوموتور؛ شایع در سالمند و غیرسازگار؛ علائم وضعیتی ممکن است در ED دیده نشود؛ سایر علل سنکوپ را رد کن","گرفتگی گرمایی: اسپاسم دردناک عضله (ساق، ران، شانه) حین ورزش؛ جایگزینی تلفات تبخیری با آب آزاد بدون نمک؛ دمای مرکزی طبیعی یا بالا","ادم گرمایی و راش گرمایی: خودمحدود در روزهای اول مواجهه؛ تورم اندام‌های آویزان یا راش در نواحی پوشیده"],"ddx":[{"n":"Other causes of syncope (arrhythmia, ACS) |","cm":1},{"n":"Heat stroke |","cm":1},{"n":"Electrolyte disturbance / rhabdomyolysis |"}],"redflags":["دمای مرکزی > 40، تغییر هوشیاری (به heat stroke ارتقا ده)"],"guide":"علائم معمولاً بدون درمان برطرف و ترخیص. ادم گرمایی: بالا نگه داشتن اندام یا جوراب فشاری؛ دیورتیک کمبود حجم را بدتر می‌کند و باید پرهیز شود. راش گرمایی: آنتی‌هیستامین، کورتیکواستروئید موضعی کم‌قدرت یا calamine؛ لباس سبک و گشاد. سنکوپ و گرفتگی: استراحت و هیدراتاسیون خوراکی یا IV.","section":"environmental","source":"Tintinalli's Emergency Medicine Manual, 8th ed., Ch. 119: Heat Emergencies, pp. 655–657"},"hymenoptera-sting":{"id":"hymenoptera-sting","variants":[{"id":"hymenoptera-local","o":{"T":[{"t":"Remove the stinger (after stabilization); cold compress; oral antihistamine as needed"}],"Co":[{"t":"Discharge after observation; refer to allergist if severe local reaction"}]},"name":"Local reaction, single/few stings","level":"III","imp":"Hymenoptera sting, local reaction","cond":"Urgent","act":"CBR","diet":"PO","ecg":"none","cxr":"none","sc":"مرد ۳۰ ساله با یک گزش زنبور و درد و تورم موضعی.","why":"برداشتن نیش و مشاهده."},{"id":"hymenoptera-anaphylaxis","o":{"I":[{"t":"CXR portable if respiratory distress"}],"L":[{"t":"(CBC and electrolytes as per baseline set; tryptase as available)"}],"S":[{"t":"IV fluid resuscitation (normal saline bolus)","fl":[{"k":"ci","v":"caution in heart failure / pulmonary edema"}]},{"t":"Epinephrine 1:1000, 0.3–0.5 mL IM in adults (0.01 mg/kg up to 0.5 mL in children) ; continuous IV epinephrine infusion if persistent symptoms or shock","fl":[{"k":"hi","v":""}]},{"t":"Methylprednisolone 2 mg/kg IV (max 125 mg) or prednisone 1 mg/kg PO (max 60 mg)"},{"t":"Diphenhydramine 1 mg/kg IV (max 50 mg); famotidine 0.5 mg/kg IV (max 40 mg)"}],"T":[{"t":"Albuterol 2.5–5 mg nebulized for bronchospasm"},{"t":"Endotracheal intubation if airway edema"},{"t":"Remove stinger after stabilization"}],"Co":[{"t":"Admit / observation; allergist referral; prescribe epinephrine autoinjector (EpiPen); allergy alert identification"}]},"name":"Anaphylaxis after Hymenoptera sting (urticaria with airway, hypotension or bronchospasm)","level":"I","imp":"Anaphylaxis, Hymenoptera sting","cond":"Emergent","act":"CBR","diet":"NPO","ecg":"stat","cxr":"portable","o2":"high-flow oxygen","sc":"زنی ۴۰ ساله پس از گزش زنبور با کهیر منتشر، تنگی نفس، ویزینگ و فشار 70/40.","why":"epinephrine IM فوری و مایع."},{"id":"hymenoptera-urticaria-only","o":{"S":[{"t":"Diphenhydramine 1 mg/kg IV (max 50 mg); famotidine 0.5 mg/kg IV (max 40 mg)"},{"t":"Methylprednisolone 2 mg/kg IV (max 125 mg) or prednisone 1 mg/kg PO (max 60 mg)","fl":[{"k":"note","v":"no epinephrine or albuterol without other systemic manifestations"}]}],"T":[{"t":"Remove stinger; observation"}],"Co":[{"t":"Allergist referral; epinephrine autoinjector prescription"}]},"name":"Urticaria only (no other systemic features)","level":"III","imp":"Urticaria after Hymenoptera sting","cond":"Urgent","act":"CBR","diet":"PO","ecg":"none","cxr":"none","sc":"مرد ۲۵ ساله پس از گزش با کهیر منتشر اما بدون تنگی نفس و فشار طبیعی.","why":"H1، H2 و استروئید بدون epinephrine."},{"id":"hymenoptera-massive","o":{"I":[{"t":"CXR portable"}],"L":[{"t":"Electrolytes, BUN, creatinine, CPK, urinalysis (myoglobin), liver enzymes, troponin, CBC, coagulation studies"}],"S":[{"t":"IV fluid resuscitation","fl":[{"k":"ci","v":"caution in AKI, anuria, heart failure / pulmonary edema"}]},{"t":"Epinephrine IM / IV infusion, steroids, H1 and H2 blockers if anaphylaxis (as above)"}],"T":[{"t":"Remove stingers after stabilization; continuous cardiac monitoring"}],"Co":[{"t":"Admit (> 100 stings, substantial comorbidity, extremes of age, or severe systemic manifestations); nephrology if renal failure"},{"t":"Discharge only if < 100 stings, asymptomatic, no rhabdomyolysis and normal renal function after 6 h observation"}]},"name":"Massive envenomation (multiple stings, > 100, Africanized bees)","level":"I","imp":"Massive Hymenoptera envenomation","cond":"Emergent","act":"CBR","diet":"NPO","ecg":"stat","cxr":"portable","sc":"مردی ۵۰ ساله با > 150 گزش زنبور با استفراغ، اسهال، ادرار تیره و فشار 90/55.","why":"رابدومیولیز، نارسایی کلیه/کبد و آسیب میوکارد را بررسی کن."}],"ch":"120","name":"Hymenoptera stings (bees, wasps, ants) and anaphylaxis","name_fa":"گزش زنبور، زنبور سرخ و مورچه (Hymenoptera)","cc":["wound-bite","rash","hypotension-shock"],"keywords":"bee sting, wasp sting, fire ant, Africanized bee, anaphylaxis, epinephrine, EpiPen, hymenoptera, گزش زنبور, آنافیلاکسی","status":"draft","features":["واکنش موضعی: درد، اریتم، ادم و خارش؛ واکنش موضعی شدید خطر واکنش سیستمیک در مواجهه مجدد را بالا می‌برد؛ مورچه آتشین: پوستول استریل در 6 تا 24 ساعت و گاه نکروز و اسکار","سیستمیک: کهیر، آنژیوادم، هیپوتانسیون، برونکواسپاسم؛ مسمومیت عظیم (زنبور آفریقایی‌شده با حمله گروهی): استفراغ و اسهال شدید، رابدومیولیز، آسیب میوکارد، نارسایی کبد و کلیه؛ سم مورچه آتشین ممکن است با سایر Hymenoptera cross-react کند","واکنش تأخیری (5 تا 14 روز بعد): شبیه serum sickness: تب، بی‌حالی، سردرد، کهیر، لنفادنوپاتی و پلی‌آرتریت"],"ddx":[{"n":"Other causes of anaphylaxis / angioedema |","cm":1},{"n":"Cellulitis (local reaction) |"},{"n":"Serum sickness |"}],"redflags":["هیپوتانسیون، استریدور/ادم راه هوایی، ویزینگ، > 100 گزش، رابدومیولیز"],"guide":"آنافیلاکسی/آنافیلاکتوئید: مایع + epinephrine 1:1000 (0.3 تا 0.5 cc IM بزرگسال یا 0.01 mg/kg تا حداکثر 0.5 cc کودک)؛ علائم مقاوم یا شوک: انفوزیون IV؛ اینتوباسیون در ادم راه هوایی؛ استروئید (methylprednisolone 2 mg/kg حداکثر 125 mg یا prednisone 1 mg/kg PO حداکثر 60 mg)؛ H1 (diphenhydramine 1 mg/kg IV حداکثر 50 mg)؛ H2 (famotidine 0.5 mg/kg IV حداکثر 40 mg)؛ برونکواسپاسم: albuterol 2.5 تا 5 mg نبولایزر. کهیر تنها: H1 و H2 و استروئید، بدون epinephrine و albuterol. نیش پس از تثبیت برداشته شود. یک گزش با علائم جزئی: ترخیص پس از مشاهده. چند گزش: بستری اگر > 100 گزش، بیماری زمینه‌ای مهم، سن حدی یا علائم سیستمیک شدید؛ < 100 گزش بدون علامت و بدون عارضه آزمایشگاهی (بدون رابدومیولیز، کلیه طبیعی) پس از 6 ساعت مشاهده: ترخیص. همه را به آلرژیست ارجاع، epinephrine autoinjector (EpiPen) تجویز، شناسه آلرژی و آموزش مصرف در اولین علامت سیستمیک.","section":"environmental","source":"Tintinalli's Emergency Medicine Manual, 8th ed., Ch. 120: Bites and Stings, pp. 658–665"},"brown-recluse-hobo-spider-bite":{"id":"brown-recluse-hobo-spider-bite","variants":[{"id":"recluse-local","o":{"T":[{"t":"Analgesia; wound care; tetanus prophylaxis; antibiotics only if infection present"},{"t":"Serial wound evaluations for outpatients","fl":[{"k":"ci","v":"dapsone not recommended"}]}],"Co":[{"t":"Surgery only for lesions > 2 cm, deferred 2–3 weeks after the bite"}]},"name":"Brown recluse / hobo bite, local lesion","level":"III","imp":"Brown recluse spider bite, local","cond":"Urgent","act":"CBR","diet":"PO","ecg":"none","cxr":"none","sc":"زنی ۳۵ ساله با ضایعه سفت قرمز دردناک ساق پس از گزش احتمالی عنکبوت.","why":"حمایتی و پیگیری سریال زخم؛ بدون dapsone."},{"id":"recluse-systemic","o":{"L":[{"t":"CBC with smear, reticulocyte, LDH, bilirubin, coagulation studies (PT/INR, PTT, fibrinogen, D-dimer), electrolytes, BUN, creatinine, urinalysis; type and screen"}],"S":[{"t":"IV hydration","fl":[{"k":"ci","v":"caution in AKI, anuria, heart failure"}]}],"T":[{"t":"Supportive care (analgesia, tetanus prophylaxis, antibiotics if infection); no antivenom commercially available in the United States"}],"Co":[{"t":"Hospitalize patients with systemic reaction and hemolysis; nephrology / hematology as needed"}]},"name":"Loxoscelism with systemic reaction / hemolysis","level":"I","imp":"Loxoscelism with hemolysis","cond":"Emergent","act":"CBR","diet":"NPO","ecg":"once","cxr":"none","sc":"کودک ۶ ساله با نکروز ران، تب، استفراغ، ادرار تیره و رنگ‌پریدگی 2 روز پس از گزش.","why":"همولیز، کلیه و DIC."}],"ch":"120","name":"Brown recluse (Loxosceles) and hobo spider bites","name_fa":"گزش عنکبوت قهوه‌ای گوشه‌نشین و hobo","cc":["wound-bite","rash"],"keywords":"brown recluse, loxoscelism, Loxosceles reclusa, hobo spider, necrotic wound, hemolysis, dapsone, عنکبوت قهوه‌ای","status":"draft","features":["گزش اولیه بی‌درد؛ ضایعه سفت اریتماتو که طی روزها تا هفته‌ها بهبود می‌یابد؛ گاه واکنش شدید با درد فوری، تاول هموراژیک و رنگ‌پریدگی موضعی و سپس نکروز طی 3 تا 4 روز و اسکار قابل‌توجه","loxoscelism (گونه‌های آمریکای جنوبی؛ در L. reclusa نادر): علائم سیستمیک (شایع‌تر در کودک) 1 تا 3 روز: تب، لرز، استفراغ، آرترالژی، میالژی، پتشی و همولیز؛ شدید: تشنج، نارسایی کلیه، DIC و مرگ","Loxosceles سه جفت چشم (بیشتر عنکبوت‌ها هشت چشم)؛ الگوی ویولن روی سفالوتوراکس مشخص ولی غیرقابل‌اعتماد؛ تشخیص بالینی (گزش به‌ندرت دیده می‌شود)؛ آزمایش تأییدی در دسترس نیست؛ آبسه‌های موضعی اغلب به‌اشتباه Loxosceles تشخیص داده می‌شود","hobo spider: تظاهر مشابه: بی‌درد، سپس سفتی، اریتم، تاول و نکروز؛ سردرد، استفراغ، خستگی؛ آزمایش یا درمان اختصاصی ندارد"],"ddx":[{"n":"Skin abscess / MRSA (frequent misdiagnosis) |","cm":1},{"n":"Necrotizing soft tissue infection |","cm":1},{"n":"Other arthropod bite |"}],"redflags":["همولیز، نارسایی کلیه، DIC، تشنج، ضایعه > 2 cm"],"guide":"حمایتی: مسکن، پروفیلاکسی کزاز، آنتی‌بیوتیک اگر عفونت. پادزهر در آمریکا تجاری نیست و معمولاً لازم نیست. بیشتر زخم‌ها بدون مداخله بهبود. dapsone اثربخشی روشن ندارد و به‌علت عوارض توصیه نمی‌شود. ارزیابی سریال زخم برای سرپایی. علائم سیستمیک و همولیز: بستری. جراحی برای ضایعه > 2 cm و 2 تا 3 هفته بعد. hobo: ترمیم جراحی زخم زخمی شدید پس از اتمام روند نکروتیک.","section":"environmental","source":"Tintinalli's Emergency Medicine Manual, 8th ed., Ch. 120: Bites and Stings, pp. 658–665"},"black-widow-spider-bite":{"id":"black-widow-spider-bite","variants":[{"id":"black-widow-main","o":{"L":[{"t":"(CBC, electrolytes, CPK as indicated)"}],"S":[{"t":"Opioid analgesia and benzodiazepines liberally for pain and cramping"}],"T":[{"t":"Local wound care; supportive care; cardiac monitoring if hypertensive / tachycardic"}],"Co":[{"t":"Observation; discharge when pain controlled"}]},"name":"Black widow bite (pain, cramps)","level":"III","imp":"Black widow spider bite","cond":"Urgent","act":"CBR","diet":"PO","ecg":"stat","cxr":"none","sc":"مردی ۳۰ ساله با درد شدید شکم و کمر و تعریق پس از گزش عنکبوت سیاه در انبار.","why":"مسکن و بنزودیازپین؛ پادزهر فقط در شدید."},{"id":"black-widow-severe","o":{"S":[{"t":"Latrodectus antivenom (equine serum) per package insert; reserved for severe cases refractory to opioids and benzodiazepines","fl":[{"k":"ci","v":"fatal anaphylaxis described"}]},{"t":"IV opioids and benzodiazepines"}],"T":[{"t":"Continuous cardiac monitoring; local wound care"}],"Co":[{"t":"Observation after antivenom; discharge after short observation if symptoms resolve"}]},"name":"Severe black widow envenomation refractory to analgesics (antivenom)","level":"II","imp":"Severe Latrodectus envenomation","cond":"Emergent","act":"CBR","diet":"NPO","ecg":"stat","cxr":"none","sc":"زنی ۵۰ ساله با درد غیرقابل کنترل با مورفین و دیازپام، فشار 190/110.","why":"پادزهر اسب (خطر آنافیلاکسی) فقط وقتی مقاوم."}],"ch":"120","name":"Black widow spider bite","name_fa":"گزش عنکبوت بیوه سیاه","cc":["wound-bite","abdominal-pain","back-neck-pain"],"keywords":"black widow, Latrodectus, latrodectism, antivenom, muscle cramps, بیوه سیاه","status":"draft","features":["درد سوزنی فوری که به کل اندام گسترش می‌یابد؛ اریتم با ضایعه «target» ظرف 1 ساعت","میالژی منتشر (عضلات بزرگ: کمر، شکم، تنه)؛ درد شدید که روزها موج می‌زند؛ هیپرتانسیون، تاکی‌کاردی، فاسیکولاسیون، سردرد، تهوع، استفراغ، تعریق (موضعی یا منتشر)؛ نادر: میوکاردیت، پریاپیسم، تنگی نفس"],"ddx":[{"n":"Acute abdomen |","cm":1},{"n":"ACS / hypertensive emergency |","cm":1},{"n":"Other muscle spasm syndromes |"}],"redflags":["درد مقاوم به اوپیوئید و بنزودیازپین، هیپرتانسیون شدید، میوکاردیت، تنگی نفس"],"guide":"اولیه: مراقبت موضعی از زخم و حمایتی؛ مسکن و بنزودیازپین به‌طور آزاد برای کاهش درد و گرفتگی. پادزهر Latrodectus (سرم اسب) سریعاً مؤثر در موارد شدید حتی با تأخیر؛ آنافیلاکسی کشنده گزارش شده: فقط برای موارد شدید مقاوم به اوپیوئید و بنزودیازپین؛ دوز طبق بروشور. پس از پادزهر و رفع علائم: ترخیص پس از مشاهده کوتاه.","section":"environmental","source":"Tintinalli's Emergency Medicine Manual, 8th ed., Ch. 120: Bites and Stings, pp. 658–665"},"tarantula-scorpion-envenomation":{"id":"tarantula-scorpion-envenomation","variants":[{"id":"scorpion-local","o":{"T":[{"t":"Oral analgesics and/or benzodiazepines; local wound care"},{"t":"Tarantula ocular exposure: thorough slit lamp examination for embedded hairs; topical steroids"}],"Co":[{"t":"Ophthalmology for surgical removal of embedded hairs; discharge with analgesics after brief observation"}]},"name":"Scorpion sting, local / no systemic signs; tarantula bite or hair exposure","level":"III","imp":"Scorpion sting / tarantula exposure, local","cond":"Urgent","act":"CBR","diet":"PO","ecg":"none","cxr":"none","sc":"مردی با درد سوزشی و پارستزی دست پس از گزش عقرب، بدون علائم سیستمیک؛ یا کودک با چشم قرمز پس از تماس با تارانتولا.","why":"مسکن؛ slit lamp برای چشم."},{"id":"scorpion-systemic","o":{"L":[{"t":"(as clinically indicated; CPK, electrolytes if prolonged agitation / rhabdomyolysis)"}],"S":[{"t":"IV benzodiazepines and opiates"},{"t":"Equine F(ab) scorpion antivenom for high-grade systemic toxicity"}],"T":[{"t":"Airway protection; endotracheal intubation if significant hypersalivation with stridor","fl":[{"k":"note","v":"atropine has been used for secretions; supporting data lacking"}]}],"Co":[{"t":"Admit; poison center / toxicology"}]},"name":"Bark scorpion systemic toxicity (cranial nerve / motor involvement, hypersalivation)","level":"I","imp":"Scorpion envenomation with systemic toxicity","cond":"Emergent","act":"CBR","diet":"NPO","ecg":"stat","cxr":"none","sc":"کودک ۳ ساله پس از گزش عقرب با حرکات چرخان چشم، هیپرسالیواسیون، بی‌قراری و حرکات عضلانی منتشر.","why":"بنزودیازپین و پادزهر F(ab) در درجه بالا."}],"ch":"120","name":"Tarantula and scorpion envenomation","name_fa":"گزش تارانتولا و عقرب","cc":["wound-bite","eye"],"keywords":"tarantula, urticating hairs, scorpion, bark scorpion, Centruroides, tap test, scorpion antivenom, عقرب, تارانتولا","status":"draft","features":["تارانتولا: موهای خاردار؛ در قرنیه و ملتحمه عمیق فرو می‌روند و التهاب ایجاد می‌کنند؛ گزش دردناک با اریتم و ادم موضعی","عقرب: در آمریکای شمالی فقط bark scorpion (Centruroides sculpturatus) سمیت سیستمیک: درد فوری و پارستزی؛ «tap test» مثبت؛ علائم سیستمیک نادر و بیشتر در کودک: درگیری حرکتی منتشر و/یا اعصاب کرانیال (حرکت چرخان چشم، دوبینی، اشکال بلع)؛ 24 تا 48 ساعت بدون پادزهر؛ گونه‌های پرسمیت در کارائیب، آسیا و آفریقا"],"ddx":[{"n":"Airway compromise (hypersalivation) |","cm":1},{"n":"Other envenomation / seizure |"}],"redflags":["هیپرسالیواسیون و استریدور، درگیری اعصاب کرانیال، علائم ریوی"],"guide":"تارانتولا: علائم چشمی پس از تماس: معاینه کامل slit lamp؛ استروئید موضعی و مشاوره چشم‌پزشکی برای برداشتن؛ گزش: مراقبت موضعی و مسکن. عقرب: اکثر بیماران فقط مسکن خوراکی و/یا بنزودیازپین؛ علائم سیستمیک: بنزودیازپین و اوپیوئید IV؛ هیپرسالیواسیون قابل‌توجه و استریدور ممکن است اینتوباسیون بخواهد؛ atropine برای ترشحات (داده ناکافی)؛ F(ab) اسبی بسیار مؤثر در سمیت سیستمیک شدید؛ بدون علائم سیستمیک: مشاهده کوتاه و ترخیص با مسکن.","section":"environmental","source":"Tintinalli's Emergency Medicine Manual, 8th ed., Ch. 120: Bites and Stings, pp. 658–665"},"ectoparasite-bites":{"id":"ectoparasite-bites","variants":[{"id":"scabies-lice","o":{"T":[{"t":"Scabies: permethrin cream neck down (infants also scalp, temple, forehead); bathe before and again 12 h after; reapply only if mites found at 2 weeks"},{"t":"Alternative: ivermectin 200 µg/kg PO, second dose in 10 days"},{"t":"Body lice: permethrin; hair lice: pyrethrin with piperonyl butoxide after washing, reapply in 10 days; wet combing; wash clothing and bedding in hot (> 52°C) water"}],"Co":[{"t":"Discharge; treat close contacts"}]},"name":"Scabies / lice infestation","level":"III","imp":"Scabies / pediculosis","cond":"Urgent","act":"CBR","diet":"PO","ecg":"none","cxr":"none","sc":"کودک ۸ ساله با خارش شدید شبانه بین انگشتان و دور کمر و افراد خانواده مشابه.","why":"permethrin و درمان تماس‌ها."},{"id":"tick-bite-paralysis","o":{"L":[{"t":"(as clinically indicated; consider serology / CBC for tick-borne illness)"}],"T":[{"t":"Remove tick: grasp with forceps near point of attachment and pull with steady gentle traction (prompt removal essential)"},{"t":"Thorough search for engorged tick before diagnosing Guillain–Barré syndrome"}],"Co":[{"t":"Observation / admit if paralysis; follow-up for tick-borne illness"}]},"name":"Tick bite / tick paralysis","level":"II","imp":"Tick attachment (tick paralysis if ascending paralysis)","cond":"Urgent","act":"CBR","diet":"PO","ecg":"none","cxr":"none","sc":"کودک ۴ ساله با ضعف صعودی پاها و ریفلکس کاهش‌یافته؛ کنه چسبیده پشت سر.","why":"برداشتن کنه درمان قطعی؛ قبل از GBS."},{"id":"chiggers-fleas-bedbugs","o":{"T":[{"t":"Oral or topical antihistamines; calamine lotion and cool soaks; topical steroid creams for severe irritation; oral steroids in severe chigger reactions"},{"t":"Chiggers: topical permethrin or other scabicide to annihilate mites"},{"t":"Secondary infection (impetigo): topical or oral antibiotics"}],"Co":[{"t":"Discharge"}]},"name":"Chigger / flea / bed bug / kissing bug bites","level":"III","imp":"Arthropod bites (chiggers / fleas / bed bugs)","cond":"Urgent","act":"CBR","diet":"PO","ecg":"none","cxr":"none","sc":"کودک با پاپول‌های خارش‌دار زیگزاگ روی پاها یا نواحی لباس تنگ.","why":"درمان علامتی."}],"ch":"120","name":"Ectoparasite infestations and bites (scabies, ticks, chiggers, fleas, lice, bed bugs)","name_fa":"عفونت‌ها و گزش‌های انگل‌های خارجی (گال، کنه، لارو مایت، کک، شپش، ساس)","cc":["rash","wound-bite"],"keywords":"scabies, permethrin, ivermectin, tick removal, tick paralysis, chiggers, fleas, lice, pediculosis, bed bugs, kissing bug, گال, کنه, شپش, ساس","status":"draft","features":["scabies (Sarcoptes scabiei): بیشتر بین انگشتان، زیربغل، ناحیه تناسلی، صورت/سر کودک و نوک پستان زنان؛ انتقال تماس مستقیم؛ خارش شدید با «burrow»؛ مایت ماده با لبه تیغ قابل خراش دادن؛ وزیکول، پاپول، کراست و اگزمایی ممکن است تشخیص را بپوشاند","کنه‌ها: بیماری‌های منتقله: Lyme، RMSF، ehrlichiosis، babesiosis، Colorado tick fever، tularemia، tick-borne encephalitis؛ tick paralysis: فلج شل صعودی متقارن شبیه GBS؛ قبل از تشخیص GBS باید کنه چسبیده جستجو شود","chiggers: لارو مایت؛ خارش شدید؛ نقاط لباس تنگ (کمربند)؛ کودکان روی چمن: ناحیه تناسلی؛ پاپول سپس ندول؛ ممکن است تب و اریتم مولتی‌فرم","کک: زیگزاگ روی پاها و کمر؛ پونکچر هموراژیک با اریتم و کهیر؛ شپش بدن: کمر، شانه، زیربغل، گردن؛ شپش سر: تخم سفید چسبیده به ساقه مو؛ شپش ناحیه عانه از راه جنسی؛ ساس و kissing bugs: گزش بی‌درد خطی/متعدد، wheals، پاپول و بول؛ لکه تیره مدفوع روی ملحفه"],"ddx":[{"n":"Eczema / contact dermatitis |","cm":1},{"n":"Guillain–Barré syndrome (tick paralysis) |"},{"n":"Cellulitis / impetigo |"}],"redflags":["فلج صعودی (tick paralysis)، تب پس از گزش کنه"],"guide":"scabies: permethrin کرم از گردن به پایین؛ شیرخوار: سر، شقیقه و پیشانی هم؛ قبل حمام، مصرف، و 12 ساعت بعد دوباره حمام؛ تکرار فقط اگر 2 هفته بعد مایت یافت شد (خارش ممکن هفته‌ها بماند)؛ جایگزین: ivermectin 200 µg/kg PO و دوز دوم 10 روز بعد. کنه: با فورسپس نزدیک نقطه اتصال و کشیدن ثابت و ملایم؛ برداشتن سریع (انتقال وابسته به زمان). chiggers: آنتی‌هیستامین خوراکی/موضعی؛ استروئید خوراکی در شدید؛ permethrin یا اسکابیسید موضعی دیگر. کک: calamine، کمپرس سرد و آنتی‌هیستامین؛ استروئید موضعی؛ ایمپتیگو/عفونت: آنتی‌بیوتیک موضعی یا خوراکی. شپش: permethrin (بدن)؛ مو: pyrethrin با piperonyl butoxide پس از شستن و تکرار 10 روز بعد؛ شانه ریز خیس؛ لباس و ملحفه آب داغ > 52°C. ساس/kissing bug: مراقبت موضعی، استروئید موضعی و آنتی‌هیستامین خوراکی.","section":"environmental","source":"Tintinalli's Emergency Medicine Manual, 8th ed., Ch. 120: Bites and Stings, pp. 658–665"},"pit-viper-bite":{"id":"pit-viper-bite","variants":[{"id":"pit-viper-observe","o":{"L":[{"t":"CBC (platelets), coagulation tests (PT/INR, fibrinogen), urinalysis, blood typing; repeat every 4 h or per antivenom course"}],"S":[{"t":"IV access in non-envenomated extremity"}],"T":[{"t":"Cardiac monitoring; local wound care; tetanus immunization"},{"t":"Measure limb circumference at several sites above and below the wound; check every 30–60 min"},{"t":"Observe at least 6–8 h (dry bite if no findings after 8–12 h)"}],"Co":[{"t":"Consult medical toxicologist / poison control center (all pit viper bites)"},{"t":"Discharge if no evidence of envenomation after 8 h (consider 24 h admission for children with lower extremity bites)"}]},"name":"Pit viper bite, no or minimal envenomation (observe 8 h)","level":"II","imp":"Pit viper bite, minimal / no envenomation","cond":"Urgent","act":"CBR","diet":"PO","ecg":"stat","cxr":"none","sc":"مردی ۳۰ ساله با گزش مار زنگی پا؛ نیش دیده می‌شود، تورم موضعی کم.","why":"مشاهده 8 تا 12 ساعت برای dry bite و پیشرفت."},{"id":"pit-viper-antivenom","o":{"L":[{"t":"CBC, PT/INR, fibrinogen, urinalysis, type and screen; monitor CBC and coagulation every 4 h or after each course; renal function"}],"S":[{"t":"FabAV (Polyvalent Crotalidae Immune Fab) 4–6 vials IV as \"initial control\" dose, diluted in 250 mL normal saline over 1 hour; repeat 4–6 vials if control not achieved; then maintenance 2 vials at 6, 12, and 18 h after initial control","fl":[{"k":"hi","v":""},{"k":"note","v":"no skin testing; same dose in children; if allergic reaction stop infusion and give epinephrine and antihistamines"}]},{"t":"Blood components only for active bleeding from severe coagulopathy"}],"T":[{"t":"Cardiac monitoring; IV in non-envenomated extremity; wound care; tetanus immunization; serial limb circumference every 30–60 min"},{"t":"Compartment syndrome: limb elevation and additional 4–6 vials FabAV; fasciotomy only if suspected and pressures persist"}],"Co":[{"t":"Medical toxicologist / poison control center; ICU admission for severe bites / antivenom"},{"t":"Counsel on 5% risk of serum sickness (prednisone 1 mg/kg/day tapering over 1–2 weeks)"}]},"name":"Pit viper envenomation, progressive swelling / systemic effects / coagulopathy (antivenom)","level":"I","imp":"Pit viper envenomation, antivenom indicated","cond":"Emergent","act":"CBR","diet":"NPO","ecg":"stat","cxr":"none","sc":"مرد ۴۰ ساله با گزش مار زنگی دست؛ تورم تا ساعد در 2 ساعت، INR 2.5، پلاکت 70،000.","why":"FabAV تا کنترل اولیه و سپس دوزهای نگهدارنده."}],"ch":"120","name":"Pit viper (Crotalinae) snake bite","name_fa":"گزش مار زنگی/pit viper","cc":["wound-bite","limb-injury"],"keywords":"snake bite, rattlesnake, copperhead, cottonmouth, pit viper, FabAV, CroFab, antivenom, coagulopathy, compartment syndrome, مارگزیدگی, پادزهر","status":"draft","features":["دو نیش جمع‌شونده و حفره حساس به گرما بین چشم و بینی؛ فقط 25% گزش‌ها با envenomation","اثرات بسته به اندازه و گونه مار، سن و اندازه قربانی، زمان سپری‌شده و ویژگی گزش؛ نشانه اصلی: یک یا چند اثر نیش + درد و ادم پیشرونده؛ لنفادنوپاتی دردناک؛ تهوع، استفراغ و طعم فلزی؛ نادر: هیپوتانسیون، تاکی‌کاردی و شوک؛ ترومبوسیتوپنی، کوآگولوپاتی و هیپوفیبرینوژنمی","نبود هر علامتی بعد از 8 تا 12 ساعت: dry bite؛ خفیف: تورم موضعی بدون علائم سیستمیک و آزمایش طبیعی؛ شدید: تورم وسیع، علائم تهدیدکننده و اختلال شدید انعقاد؛ سندرم خفیف ممکن است طی ساعت‌ها پیشرفت کند","آزمایش: CBC، انعقاد، UA، گروه خون"],"ddx":[{"n":"Coral snake bite |","cm":1},{"n":"Soft tissue infection / cellulitis |"},{"n":"Other envenomation / dry bite |"}],"redflags":["تورم پیشرونده، کوآگولوپاتی، ترومبوسیتوپنی، هیپوتانسیون، سندرم کمپارتمان"],"guide":"مشاوره سم‌شناس/مرکز سموم در همه. مانیتور قلبی و IV در اندام غیرگزیده. مراقبت زخم و کزاز. دور اندام چند نقطه بالا و پایین زخم هر 30 تا 60 دقیقه. تورم پیشرونده، علائم سیستمیک یا کوآگولوپاتی: FabAV (Polyvalent Crotalidae Immune Fab، ساخته‌شده از گوسفند) بدون تست پوستی؛ «initial control» دوز 4 تا 6 ویال IV (پایان پیشرفت همه اجزا: موضعی، سیستمیک و آزمایشگاهی)؛ هر دوز در 250 mL NS طی 1 ساعت؛ دوز کودک و بزرگسال یکسان (حجم رقیق‌کننده کمتر در کودک کوچک)؛ واکنش آلرژیک: قطع و epinephrine و آنتی‌هیستامین. عدم کنترل: تکرار 4 تا 6 ویال. CBC و انعقاد هر 4 ساعت یا بعد هر دوره (هر کدام بیشتر) و کلیه. نگهداری: دوز 2 ویال در ساعت 6، 12 و 18 پس از کنترل اولیه. سندرم کمپارتمان نادر: بالا بردن اندام و 4 تا 6 ویال دیگر؛ فاسیوتومی فقط اگر مشکوک و فشار بالا علی‌رغم این؛ خونریزی فعال: فرآورده خونی (FabAV ستون درمان). مشاهده ≥ 6 تا 8 ساعت؛ شدید یا دریافت آنتی‌ونین: ICU؛ بدون envenomation پس از 8 ساعت: ترخیص (بعضی کودکان با گزش اندام تحتانی را 24 ساعت بستری می‌کنند). مشاوره درباره 5% خطر serum sickness: prednisone 1 mg/kg/d با کاهش تدریجی طی 1 تا 2 هفته.","section":"environmental","source":"Tintinalli's Emergency Medicine Manual, 8th ed., Ch. 120: Bites and Stings, pp. 658–665"},"coral-snake-gila-monster-bite":{"id":"coral-snake-gila-monster-bite","variants":[{"id":"coral-snake","o":{"I":[{"t":"CXR portable if respiratory compromise"}],"L":[{"t":"Pulmonary function parameters (inspiratory pressure, vital capacity); CBC, electrolytes, CPK"}],"S":[{"t":"Coral snake antivenom (Micrurus fulvius) 3–5 vials at first sign of toxicity; additional doses if symptoms appear","fl":[{"k":"note","v":"access extremely limited; no longer manufactured in the United States"}]}],"T":[{"t":"Follow pulmonary function parameters and neurological examinations; airway management; wound care; tetanus"}],"Co":[{"t":"Medical toxicologist / poison control center; admit 24–48 hours"}]},"name":"Eastern coral snake bite","level":"I","imp":"Coral snake bite, risk of neurotoxicity","cond":"Emergent","act":"CBR","diet":"NPO","ecg":"stat","cxr":"portable","sc":"کودک ۱۰ ساله پس از گزش مار با نوارهای قرمز/زرد؛ دیزآرتری و پتوز.","why":"آنتی‌ونین زود و پایش تنفس."},{"id":"gila-monster","o":{"T":[{"t":"Remove the reptile (place on solid surface to loosen bite); standard wound care including search for implanted teeth; tetanus"},{"t":"Observe for airway edema at least 6 hours after removal","fl":[{"k":"note","v":"no further treatment required"}]}],"Co":[{"t":"Discharge if no systemic manifestations (including angioedema)"}]},"name":"Gila monster bite","level":"III","imp":"Gila monster bite","cond":"Urgent","act":"CBR","diet":"PO","ecg":"none","cxr":"none","sc":"مردی با گزش Gila monster به دست و تورم و درد؛ جانور هنوز چسبیده.","why":"جدا کردن جانور و مشاهده 6 ساعت برای ادم راه هوایی."}],"ch":"120","name":"Coral snake and Gila monster bites","name_fa":"گزش مار مرجانی و Gila monster","cc":["wound-bite","focal-neuro"],"keywords":"coral snake, Micrurus fulvius, elapid, neurotoxin, antivenom, Gila monster, مار مرجانی","status":"draft","features":["coral snake (Elapidae) آمریکا: نوارهای قرمز و زرد مجاور؛ فقط eastern coral snake (Micrurus fulvius fulvius) درمان قابل‌توجه می‌خواهد: نوروتوکسین قوی: لرزش، هیپرسالیواسیون، فلج تنفسی، تشنج و فلج بولبار (دیزآرتری، دوبینی، دیسفاژی)؛ گزش Sonoran (Arizona) خفیف","Gila monster: درد و تورم؛ سمیت سیستمیک نادر: تعریق، پارستزی، ضعف، هیپرتانسیون و آنژیوادم؛ جانور محکم می‌چسبد"],"ddx":[{"n":"Pit viper bite |","cm":1},{"n":"Guillain–Barré / botulism |"}],"redflags":["ضعف بولبار، دیسپنه، کاهش ظرفیت حیاتی"],"guide":"coral snake: مشاوره سم‌شناس؛ اثرات سمی قابل پیشگیری ولی به‌سختی برگشت‌پذیر: همه گزیده‌شدگان 3 تا 5 ویال آنتی‌ونین (M. fulvius) در اولین علامت سمیت؛ دوز بیشتر با بروز علائم؛ دسترسی بسیار محدود (در آمریکا دیگر ساخته نمی‌شود). پایش پارامترهای ریوی و معاینه عصبی (inspiratory pressure و vital capacity) و بستری 24 تا 48 ساعت. Gila monster: جدا کردن جانور (روی سطح محکم قرار دادن)؛ مراقبت استاندارد و جستجوی دندان باقی‌مانده؛ مشاهده ≥ 6 ساعت از نظر ادم راه هوایی؛ بدون علائم سیستمیک: ترخیص.","section":"environmental","source":"Tintinalli's Emergency Medicine Manual, 8th ed., Ch. 120: Bites and Stings, pp. 658–665"},"marine-wound-infection":{"id":"marine-wound-infection","variants":[{"id":"marine-wound-minor","o":{"I":[{"t":"Soft tissue radiograph or ultrasound if retained foreign body suspected"}],"T":[{"t":"Copious irrigation; explore for foreign matter and debride devitalized tissue; leave open for delayed primary closure; update tetanus","fl":[{"k":"ci","v":"prophylactic antibiotics not indicated for routine minor wounds in healthy patients"}]}],"Co":[{"t":"Discharge with wound-care instructions and follow-up"}]},"name":"Minor marine wound / coral scrape, healthy patient, early care","level":"III","imp":"Marine wound, minor","cond":"Urgent","act":"CBR","diet":"PO","ecg":"none","cxr":"none","sc":"غواص سالم با خراش مرجان روی ساق؛ زخم سطحی بدون جسم خارجی.","why":"شستشو و مراقبت زخم؛ بدون آنتی‌بیوتیک."},{"id":"marine-wound-prophylaxis","o":{"I":[{"t":"Soft tissue radiograph or ultrasound for foreign body (especially if intra-articular)"}],"L":[{"t":"Wound culture (sensitivity); CBC if systemic signs"}],"A":[{"t":"Cephalexin 500 mg PO four times daily (children 10–25 mg/kg) or doxycycline 100 mg PO twice daily (adults, MRSA coverage) for Staphylococcus / Streptococcus"},{"t":"Add ceftriaxone 1 g IV daily (children 50 mg/kg) or a fluoroquinolone (levofloxacin or ciprofloxacin 500 mg PO daily) for Vibrio (ocean)","fl":[{"k":"ci","v":"avoid fluoroquinolones in children"}]},{"t":"Freshwater (Aeromonas): fluoroquinolone, third-generation cephalosporin, or trimethoprim-sulfamethoxazole DS 1 tablet PO twice daily (children 4 mg/kg trimethoprim)"}],"T":[{"t":"Copious irrigation, exploration and debridement; remove foreign bodies; leave open for delayed closure; update tetanus"},{"t":"Mycobacterium marinum granuloma: months of clarithromycin or rifampin plus ethambutol"}],"Co":[{"t":"Follow-up in 24–48 h; admit if progressive inflammation"}]},"name":"Higher-risk marine wound (deep, delayed care, retained FB, comorbidity) — oral antibiotic prophylaxis / early infection","level":"II","imp":"Marine-associated wound, high infection risk / early infection","cond":"Urgent","act":"CBR","diet":"PO","ecg":"none","cxr":"none","sc":"ماهیگیر ۵۵ ساله دیابتی با زخم عمیق دست پس از خار ماهی و تورم و قرمزی ۲ روز بعد.","why":"آنتی‌بیوتیک بر اساس شرایط؛ Vibrio در آب شور."},{"id":"marine-wound-severe","o":{"I":[{"t":"Soft tissue radiograph / ultrasound for foreign bodies; CT as indicated"}],"L":[{"t":"CBC, electrolytes, BUN, creatinine, lactate, coagulation studies, blood cultures, wound culture; type and crossmatch for hemorrhage"}],"S":[{"t":"IV crystalloid / blood products for hemorrhagic shock","fl":[{"k":"ci","v":"caution in heart failure / pulmonary edema"}]}],"A":[{"t":"Cefazolin 1–2 g IV every 8 h (children 25 mg/kg) plus ceftriaxone 1 g IV daily (children 50 mg/kg) or cefotaxime 2 g IV every 8 h (children 50 mg/kg), plus doxycycline 100 mg IV twice daily (adults) or fluoroquinolone (not children) for Vibrio","fl":[{"k":"hi","v":""}]},{"t":"Freshwater: imipenem 500 mg IV every 6 h (children 10–25 mg/kg) covers Aeromonas"}],"T":[{"t":"Hemorrhage control, irrigation, exploration, surgical debridement; leave wounds open; tetanus"}],"Co":[{"t":"Surgery (trauma / orthopedic / plastic); ICU; infectious disease"}]},"name":"Major marine trauma or severe marine infection (shark bite, Vibrio necrotizing infection, IV antibiotics)","level":"I","imp":"Major marine trauma / severe marine wound infection","cond":"Emergent","act":"CBR","diet":"NPO","ecg":"stat","cxr":"portable","sc":"مرد ۶۰ ساله دچار سیروز با تاول هموراژیک، درد شدید و شوک پس از زخم پا در آب دریا؛ یا مصدوم گاز کوسه با خونریزی شدید پا.","why":"کنترل خونریزی/احیا، آنتی‌بیوتیک IV و جراحی."}],"ch":"121","name":"Marine trauma and marine-associated wound infection","name_fa":"ترومای دریایی و عفونت زخم‌های دریایی","cc":["wound-bite","environmental","fever"],"keywords":"shark bite, marine wound, Vibrio vulnificus, Aeromonas, Erysipelothrix, Mycobacterium marinum, coral cut, fish handler, زخم دریایی, ویبریو","status":"draft","features":["ترومای عمده: کوسه، باراکودا، مارماهی moray، فک، تمساح، needlefish، wahoo، piranha، triggerfish؛ گاز کوسه: از دست رفتن بافت قابل‌توجه (به‌ویژه پا) و شوک هموراژیک؛ ترومای جزئی: بریدگی و خراش مرجان: درد سوزشی موضعی، اریتم، کهیر و خارش","زخم دریایی: فلور معمول پوست (Staphylococcus و Streptococcus) + باکتری‌های ویژه دریا؛ خطرناک‌ترین Vibrio (گرم‌منفی هالوفیل): عفونت سریع: درد، تورم، تاول هموراژیک، واسکولیت، نکروتیزان فاشیئیت و سپسیس؛ مبتلایان به سرکوب ایمنی (به‌ویژه بیماری کبدی): سپسیس و مرگ (تا 60%) با V. vulnificus","Erysipelothrix rhusiopathiae (fish-handler's disease): پلاک‌های حاشیه‌دار دردناک پس از پونکچر؛ Mycobacterium marinum (اسیدفاست): گرانولوم پوستی مزمن 3 تا 4 هفته بعد؛ آب شیرین: Aeromonas"],"ddx":[{"n":"Necrotizing fasciitis / Vibrio sepsis |","cm":1},{"n":"Cellulitis / abscess |"},{"n":"Retained foreign body / osteomyelitis |"}],"redflags":["تاول هموراژیک، بیماری کبدی یا سرکوب ایمنی، شوک، درگیری استخوان/مفصل"],"guide":"شستشوی فراوان زخم‌های پاره، سوراخ و گاز؛ جستجوی جسم خارجی و دبریدمان بافت غیرزنده؛ رادیوگرافی نسج نرم یا سونوگرافی برای یافتن جسم خارجی (برداشتن به‌ویژه داخل مفصل)؛ بازگذاشتن زخم برای بستن اولیه تأخیری؛ کزاز. آنتی‌بیوتیک پروفیلاکسی برای زخم‌های جزئی روتین در بیمار سالم لازم نیست (جدول 121-1): بدون آنتی‌بیوتیک: بیمار سالم، مراقبت سریع، بدون جسم خارجی/استخوان/مفصل، آسیب کوچک/سطحی؛ پروفیلاکسی/سرپایی: مراقبت دیر، تروما بزرگ، بیماری زمینه‌ای، تأخیر طولانی، زخم عمیق، جسم خارجی باقی‌مانده؛ بستری IV: التهاب پیشرونده، نفوذ به پریوست/مفصل/حفره بدن، آسیب عمده همراه با envenomation یا بیماری سیستمیک. Staphylococcus/Streptococcus: cephalexin 500 mg PO چهار بار در روز (کودک 10 تا 25 mg/kg) یا cefazolin 1 تا 2 g IV هر 8 ساعت (کودک 25 mg/kg)؛ جایگزین: doxycycline 100 mg PO/IV دو بار روزانه (پوشش MRSA در بزرگسال). افزودن ceftriaxone 1 g IV روزانه (کودک 50 mg/kg) یا cefotaxime 2 g IV هر 8 ساعت (کودک 50 mg/kg) یا فلوروکینولون (levofloxacin یا ciprofloxacin 500 mg PO/IV روزانه؛ در کودک نه) برای Vibrio. Aeromonas (آب شیرین): فلوروکینولون یا سفالوسپورین نسل 3 یا TMP-SMX DS 1 قرص دو بار روزانه (کودک 4 mg/kg trimethoprim) یا imipenem 500 mg (کودک 10 تا 25 mg/kg) IV هر 6 ساعت. M. marinum: ماه‌ها clarithromycin یا rifampin + ethambutol.","section":"environmental","source":"Tintinalli's Emergency Medicine Manual, 8th ed., Ch. 121: Trauma and Envenomation from Marine Fauna, pp. 666–669"},"marine-envenomation-cnidaria":{"id":"marine-envenomation-cnidaria","variants":[{"id":"cnidaria-local","o":{"T":[{"t":"Irrigate with seawater or saline; remove tentacles and nematocysts; hot water immersion 43.3–45.6°C (111–114°F) until pain relieved; topical lidocaine"},{"t":"Box jellyfish: topical 5% acetic acid (vinegar)"},{"t":"Topical corticosteroid for itching; observe for development of systemic symptoms","fl":[{"k":"note","v":"treatment controversial / species dependent"}]}],"Co":[{"t":"Discharge after observation"}]},"name":"Local jellyfish / man-of-war / fire coral sting","level":"III","imp":"Cnidarian sting, local reaction","cond":"Urgent","act":"CBR","diet":"PO","ecg":"none","cxr":"none","sc":"شناگر با راش خطی دردناک و خارش پس از تماس با شاخک جلیفیش.","why":"آبشویی دریا، آب گرم و lidocaine."},{"id":"cnidaria-box-irukandji","o":{"I":[{"t":"CXR portable (pulmonary edema)"}],"L":[{"t":"Troponin, electrolytes (Mg, K, Ca), blood gas as indicated"}],"S":[{"t":"Chironex antivenin (box jellyfish, per local protocol); parenteral opioids for pain"},{"t":"Magnesium for cardiac arrest"}],"T":[{"t":"Irrigate with saline or seawater; hot water immersion; remove tentacles and nematocysts; topical 5% acetic acid (vinegar) for box jellyfish; topical lidocaine"},{"t":"Continuous cardiac monitoring; supportive care"}],"Co":[{"t":"Admit ICU / monitored bed; toxicology / poison center"}]},"name":"Box jellyfish or Irukandji syndrome (systemic)","level":"I","imp":"Box jellyfish / Irukandji envenomation","cond":"Emergent","act":"CBR","diet":"NPO","ecg":"stat","cxr":"portable","sc":"شناگر پس از گزش در آب استرالیا با درد منتشر، هیپرتانسیون 200/110، تاکی‌کاردی، تعریق و تنگی نفس.","why":"مسکن اوپیوئیدی، پایش قلبی و پادزهر Chironex؛ منیزیم در ایست."}],"ch":"121","name":"Jellyfish, Portuguese man-of-war and other cnidarian stings","name_fa":"گزش عروس دریایی، Portuguese man-of-war و سایر Cnidaria","cc":["wound-bite","rash","environmental"],"keywords":"jellyfish, box jellyfish, Chironex, Irukandji, Portuguese man-of-war, Physalia, fire coral, anemone, seabather's eruption, vinegar, عروس دریایی","status":"draft","features":["Cnidaria سلول‌های گزنده (nematocyst) دارند: درد موضعی، تورم، خارش، کهیر و گاه تاول و نکروز؛ برخی واکنش سیستمیک","Hydrozoans: hydroids، Millepora (fire coral) و Physalia (Portuguese man-of-war): راش خطی اریتماتو؛ نادراً ایست تنفسی (احتمالاً آنافیلاکسی)","Scyphozoans (عروس دریایی حقیقی): شکل‌های لاروی اقیانوس اطلس: درماتیت پایدار زیر لباس شنا روزها (Seabather's eruption)","Cubozoans (box jellyfish): Chironex fleckeri (استرالیا) و Chiropsalmus (خلیج مکزیک): مرگ قلبی-سمی بعد از گزش شدید؛ Carybdea (هاوایی): گزش دردناک بدون مرگ؛ Carukia barnesi: سندرم Irukandji: درد منتشر، هیپرتانسیون، تاکی‌کاردی، تعریق و حتی ادم ریوی","Anthozoans (anemone): واکنش موضعی خفیف؛ Porifera (اسفنج): درماتیت خارشی گزنده با spicule؛ Annelida (کرم‌های خاردار و آتشین): خار در پوست، درد و اریتم"],"ddx":[{"n":"Anaphylaxis |","cm":1},{"n":"Contact dermatitis |"},{"n":"Irukandji syndrome vs sympathomimetic toxicity / ACS |"}],"redflags":["شوک، ایست قلبی-تنفسی (box jellyfish)، هیپرتانسیون شدید و ادم ریوی (Irukandji)"],"guide":"درمان جلیفیش بحث‌برانگیز و وابسته به گونه؛ آبشویی اولیه با آب دریا برای برداشتن شاخک‌های حاوی nematocyst مفید است؛ آب گرم (43.3 تا 45.6°C / 111 تا 114°F) و lidocaine موضعی ممکن است اثر سم موضعی را کم کند (جدول 121-2). غیرنافذ: fire coral، hydroid، anemone: شستشو با آب دریا یا سالین؛ Portuguese man-of-war، bluebottle و جلیفیش غیر box: غوطه‌وری در آب گرم، شستشوی آب دریا، lidocaine موضعی، برداشتن شاخک‌ها و nematocyst؛ box jellyfish: غوطه‌وری آب گرم، شستشو با سالین/آب دریا، سرکه (acetic acid 5%) موضعی، برداشتن شاخک، lidocaine موضعی، اوپیوئید تزریقی برای درد، پادزهر Chironex، منیزیم برای ایست قلبی؛ Irukandji: شستشو، آب گرم، برداشتن شاخک‌ها، حمایتی. اسفنج: سرکه 5% و استروئید موضعی؛ کرم خاردار: برداشتن خارها، استروئید موضعی برای خارش؛ استروئید موضعی برای خارش و مشاهده برای علائم سیستمیک.","section":"environmental","source":"Tintinalli's Emergency Medicine Manual, 8th ed., Ch. 121: Trauma and Envenomation from Marine Fauna, pp. 666–669"},"marine-envenomation-penetrating":{"id":"marine-envenomation-penetrating","variants":[{"id":"marine-spine-envenomation","o":{"I":[{"t":"Soft tissue radiograph or ultrasound to assess for retained spines"}],"T":[{"t":"Hot water immersion 43.3–45.6°C (111–114°F) until pain relieved; lidocaine infiltration (sea urchin: topical lidocaine, topical 5% acetic acid)"},{"t":"Usual wound care: irrigate, explore, debride, remove spines, consider antibiotics and analgesia; tetanus"},{"t":"Stonefish: antivenin if severe systemic reaction; observe for systemic symptoms"}],"A":[{"t":"Antibiotics per wound-risk table (see marine wound infection) if retained spine / high risk"}],"Co":[{"t":"Discharge after observation; surgical exploration if retained spine"}]},"name":"Stingray / lionfish / catfish / stonefish / sea urchin spine","level":"III","imp":"Marine spine envenomation","cond":"Urgent","act":"CBR","diet":"PO","ecg":"none","cxr":"none","sc":"شناگر با پونکچر دردناک پا پس از پا گذاشتن روی سفره‌ماهی.","why":"آب گرم، lidocaine و جستجوی خار."},{"id":"marine-neurotoxic-envenomation","o":{"I":[{"t":"CXR portable (respiratory compromise)"}],"L":[{"t":"CPK (sea snake myotoxicity), electrolytes, BUN, creatinine, urinalysis (myoglobin)"}],"S":[{"t":"Sea snake antivenom if severe systemic reaction"}],"T":[{"t":"Pressure immobilization; airway management and ventilatory support as needed (supportive care for blue-ringed octopus / cone snail)"},{"t":"Observe 8 h for myotoxicity / neurotoxicity (sea snake)"}],"Co":[{"t":"ICU; toxicology / poison center"}]},"name":"Neurotoxic marine envenomation (sea snake, blue-ringed octopus, cone snail)","level":"I","imp":"Neurotoxic marine envenomation (paralytic)","cond":"Emergent","act":"CBR","diet":"NPO","ecg":"stat","cxr":"portable","o2":"high-flow oxygen","sc":"غواص پس از گزش هشت‌پای حلقه‌آبی با بی‌حسی دهان، ضعف و دیسپنه سریع.","why":"pressure immobilization و حمایت تنفسی."}],"ch":"121","name":"Penetrating marine envenomation (stingray, spined fish, sea urchin, cone snail, blue-ringed octopus, sea snake)","name_fa":"گزش نافذ دریایی (سفره‌ماهی، ماهی خاردار، خارپشت دریایی، حلزون مخروطی، هشت‌پا، مار دریایی)","cc":["wound-bite","environmental","focal-neuro"],"keywords":"stingray, lionfish, stonefish, scorpionfish, catfish, sea urchin, cone snail, blue-ringed octopus, sea snake, hot water immersion, pressure immobilization, سفره ماهی, مار دریایی","status":"draft","features":["مهره‌داران: stingray (خار سمی دم، پونکچر/پارگی با درد شدید موضعی)، ماهی‌های خاردار (scorpion fish، lionfish، catfish، weeverfish، stonefish): غدد سم پس از سوراخ شدن: درد، اریتم و ادم؛ خار باقی‌مانده: عفونت؛ مار دریایی (Indo-Pacific): نوروتوکسیسیتی و میوتوکسیسیتی، مرگ از فلج صعودی","خارپشت دریایی: درد فوری، گاهی سم با اریتم و تورم؛ خار باقی‌مانده: عفونت و گرانولوم؛ crown-of-thorns sea star: درد سوزشی و التهاب موضعی؛ sea cucumber: درماتیت خفیف","Mollusca: cone shell (Indo-Pacific Conus) و blue-ringed octopus (Hapalochlaena): سم فلج‌کننده با فلج تنفسی سریع"],"ddx":[{"n":"Anaphylaxis |","cm":1},{"n":"Retained spine / foreign body infection |"},{"n":"Neuromuscular paralysis of other cause |"}],"redflags":["ضعف تنفسی/فلج، شوک، گزش مار دریایی، گزش stonefish"],"guide":"جدول 121-2: stingray/lionfish/catfish/scorpionfish: غوطه‌وری آب گرم (43.3 تا 45.6°C تا رفع درد) و infiltrate lidocaine؛ مراقبت معمول (شستشو، اکتشاف، دبریدمان، آنتی‌بیوتیک و مسکن)؛ جستجوی خار stingray (رادیوگرافی یا اکتشاف)؛ مشاهده علائم سیستمیک. stonefish: همین + آنتی‌ونین stonefish در واکنش سیستمیک شدید. sea snake: pressure immobilization؛ آنتی‌ونین در واکنش سیستمیک شدید؛ مشاهده 8 ساعت از نظر میوتوکسیسیتی/نوروتوکسیسیتی. blue-ringed octopus و cone snail: pressure immobilization و حمایتی (تنفسی). sea urchin: غوطه‌وری آب گرم، lidocaine موضعی، سرکه 5%، اکتشاف زخم و برداشتن خار، استروئید موضعی؛ fireworms: برداشتن bristle و استروئید موضعی برای خارش.","section":"environmental","source":"Tintinalli's Emergency Medicine Manual, 8th ed., Ch. 121: Trauma and Envenomation from Marine Fauna, pp. 666–669"},"acute-mountain-sickness":{"id":"acute-mountain-sickness","variants":[{"id":"ams-mild","o":{"L":[{"t":"(SpO2 monitoring; labs not usually required)"}],"T":[{"t":"Terminate further ascent until symptoms resolve"},{"t":"Analgesic (acetaminophen or NSAID); ondansetron ODT 4–8 mg PO every 4–6 h"},{"t":"Low-flow oxygen if available"}],"Co":[{"t":"Discharge with counseling on graded ascent and prophylaxis"}]},"name":"Mild AMS","level":"III","imp":"Acute mountain sickness, mild","cond":"Urgent","act":"CBR","diet":"PO","ecg":"once","cxr":"none","sc":"کوهنورد ۳۰ ساله در 3500 m با سردرد، تهوع و بی‌خوابی بدون آتاکسی.","why":"قطع صعود و درمان علامتی."},{"id":"ams-moderate","o":{"I":[{"t":"CXR PA if rales / dyspnea (rule out HAPE)"}],"L":[{"t":"(SpO2; electrolytes, glucose as indicated)"}],"S":[{"t":"Acetazolamide 125–250 mg PO twice daily (children 2.5 mg/kg) until symptoms resolve","fl":[{"k":"ci","v":"sulfa allergy"}]},{"t":"Dexamethasone 4 mg PO, IM or IV every 6 h with taper over several days"}],"T":[{"t":"Descent 300–1000 m (immediate descent if mental status change, ataxia, or pulmonary edema); low-flow oxygen; hyperbaric therapy if descent not possible"},{"t":"Ondansetron 4–8 mg PO every 4–6 h; analgesic"}],"Co":[{"t":"Discharge if good response; counsel graded ascent, acetazolamide prophylaxis starting 1 day before ascent, avoid overexertion, alcohol and respiratory depressants"}]},"name":"Moderate AMS","level":"II","imp":"Acute mountain sickness, moderate","cond":"Urgent","act":"CBR","diet":"PO","ecg":"once","cxr":"PA","sc":"مرد ۴۰ ساله با سردرد شدید، استفراغ، ضعف و الیگوری پس از صعود سریع به 4200 m.","why":"نزول 300 تا 1000 m؛ acetazolamide و dexamethasone."}],"ch":"122","name":"Acute mountain sickness (AMS)","name_fa":"بیماری حاد کوهستان (AMS)","cc":["headache","nausea-vomiting","environmental"],"keywords":"acute mountain sickness, AMS, altitude sickness, acetazolamide, dexamethasone, descent, بیماری ارتفاع, استازولامید","status":"draft","features":["معمولاً در افراد سازگار نشده با صعود سریع به ارتفاع > 2000 m؛ علائم شبیه خماری تا 6 ساعت پس از ورود (گاه تا یک روز تأخیر): سردرد دوطرفه فرونتال همراه ترکیبی از علائم GI، سرگیجه، خستگی یا اختلال خواب؛ بدتر شدن سردرد، استفراغ، الیگوری، تنگی نفس و ضعف = پیشرفت","معاینه محدود: هیپوتانسیون وضعیتی، ادم محیطی و صورت، رال موضعی (تا 20%)؛ فوندوس: وریدهای پرپیچ و متسع؛ خونریزی شبکیه شایع در > 5000 m؛ SaO2 استراحت معمولاً طبیعی برای ارتفاع و با تشخیص همبسته ضعیف","تشخیص بر اساس سابقه صعود سریع و علائم؛ افتراق: هیپوترمی، مسمومیت CO، عفونت ریوی/CNS، میگرن، دهیدراتاسیون و خستگی شدید"],"ddx":[{"n":"CO poisoning / hypothermia |","cm":1},{"n":"HAPE / HACE |","cm":1},{"n":"Migraine / dehydration / exhaustion |"},{"n":"Pulmonary or CNS infection |"}],"redflags":["تغییر هوشیاری، آتاکسی، ادم ریوی (ارتقا به HACE/HAPE)"],"guide":"اهداف: جلوگیری از پیشرفت، قطع بیماری و بهبود سازگاری. قطع صعود تا برطرف شدن علائم. خفیف: مسکن (acetaminophen یا NSAID) و ضداستفراغ (ondansetron ODT 4 تا 8 mg PO هر 4 تا 6 ساعت)؛ معمولاً در 12 تا 36 ساعت با توقف صعود بهبود. نزول 300 تا 1000 m سریعاً علائم را رفع می‌کند؛ نزول فوری و درمان برای AMS متوسط یا تغییر هوشیاری، آتاکسی یا ادم ریوی. اکسیژن کم‌جریان. اکسیژن هیپرباریک برای AMS متوسط اگر نزول ممکن نیست. دارو برای متوسط: acetazolamide 125 تا 250 mg بزرگسال و 2.5 mg/kg کودک PO دو بار روزانه تا رفع علائم؛ و dexamethasone 4 mg PO/IM/IV هر 6 ساعت با کاهش تدریجی طی چند روز. اندیکاسیون acetazolamide: سابقه بیماری ارتفاع، صعود ناگهانی > 3000 m، AMS، تنفس دوره‌ای علامت‌دار در خواب؛ اثر: دیورز بیکربنات و اسیدوز متابولیک (پیشگیری و درمان)؛ در آلرژی سولفا اجتناب. بیماران با پاسخ خوب ترخیص: مشاوره: صعود تدریجی، پروفیلاکسی با acetazolamide از یک روز قبل تا حداقل دو روز پس از رسیدن، پرهیز از فعالیت شدید، الکل و داروهای مضعف تنفس.","section":"environmental","source":"Tintinalli's Emergency Medicine Manual, 8th ed., Ch. 122: High-Altitude Disorders, pp. 670–672"},"hape":{"id":"hape","variants":[{"id":"hape-main","o":{"I":[{"t":"CXR portable (interstitial → alveolar infiltrates)"}],"L":[{"t":"(CBC, electrolytes, troponin as needed to exclude alternatives; SaO2 monitoring)"}],"S":[{"t":"Nifedipine 20–30 mg extended release PO every 12 h or tadalafil 10 mg PO twice daily (if descent / oxygen unavailable)","fl":[{"k":"ci","v":"hypotension"}]}],"T":[{"t":"Supplemental oxygen titrated to SaO2 ≥ 90%; rest, keep warm"},{"t":"Immediate descent (minimize exertion); hyperbaric treatment if descent not possible"},{"t":"Albuterol inhaled 2–4 puffs every 4–6 h (not well studied)"}],"Co":[{"t":"Admit; discharge when clinical and radiographic improvement and room air SaO2 > 90%"}]},"name":"HAPE","level":"I","imp":"High-altitude pulmonary edema","cond":"Emergent","act":"CBR","diet":"NPO","ecg":"stat","cxr":"portable","o2":"titrate to SaO2 ≥ 90%","sc":"کوهنورد ۳۵ ساله شب سوم در 4500 m با تنگی نفس در استراحت، سرفه صورتی و SpO2 72%.","why":"اکسیژن و نزول فوری؛ بدون فعالیت."}],"ch":"122","name":"High-altitude pulmonary edema (HAPE)","name_fa":"ادم ریوی ارتفاع (HAPE)","cc":["dyspnea","cough-hemoptysis","environmental"],"keywords":"HAPE, high altitude pulmonary edema, nifedipine, tadalafil, descent, ادم ریوی ارتفاع","status":"draft","features":["عوامل خطر: صعود سریع، فعالیت شدید، سرما، هیپرتانسیون ریوی، داروی خواب؛ کودک با عفونت تنفسی حساس‌تر؛ ممکن است کشنده باشد","معمولاً شب دوم تا چهارم در ارتفاع جدید: سرفه خشک و کاهش ظرفیت ورزش → تنگی نفس در استراحت، سرفه خلط‌دار، ضعف شدید و سیانوز؛ تاکی‌کاردی، تاکی‌پنه، رال، علائم هیپرتانسیون ریوی (P2 برجسته و heave بطن راست)؛ SaO2 استراحت پایین برای ارتفاع و با فعالیت بسیار افت می‌کند","CXR: بینابینی → موضعی → آلوئولار منتشر؛ ECG: انحراف محور راست و strain بطن راست","افتراق: پنومونی، آسم، CHF، ایسکمی میوکارد، PE؛ کاهش عملکرد ورزشی و سرفه خشک برای شک زودرس کافی؛ پاسخ به درمان کلید تشخیص"],"ddx":[{"n":"Pneumonia |","cm":1},{"n":"CHF / myocardial ischemia |","cm":1},{"n":"Acute asthma / PE |"}],"redflags":["SaO2 پایین، سیانوز، تغییر هوشیاری (HACE همزمان)"],"guide":"شناسایی زودهنگام ضروری. استراحت و گرم نگه داشتن. اکسیژن تکمیلی و تیتر به SaO2 ≥ 90%. نزول فوری درمان انتخابی؛ حداقل فعالیت حین نزول؛ هیپرباریک اگر نزول ممکن نیست؛ موارد بسیار خفیف: استراحت و اکسیژن. دارو معمولاً لازم نیست اگر نزول و اکسیژن در دسترس؛ در شرایط میدانی: nifedipine 20 تا 30 mg آهسته‌رهش PO هر 12 ساعت یا tadalafil 10 mg PO دو بار روزانه (کاهش vasoconstriction هیپوکسیک)؛ همچنین پروفیلاکسی برای سابقه HAPE؛ albuterol استنشاقی 2 تا 4 پاف هر 4 تا 6 ساعت (مطالعه ناکافی). ترخیص: بهبود بالینی و رادیوگرافیک و SaO2 هوای اتاق > 90%.","section":"environmental","source":"Tintinalli's Emergency Medicine Manual, 8th ed., Ch. 122: High-Altitude Disorders, pp. 670–672"},"hace":{"id":"hace","variants":[{"id":"hace-main","o":{"I":[{"t":"CT head / MRI brain (T2 signal in splenium of corpus callosum) as indicated and not delaying treatment"},{"t":"CXR portable (concurrent HAPE)"}],"L":[{"t":"Glucose (bedside), electrolytes, CBC; arterial blood gas if intubated (avoid PaCO2 < 30 mmHg)"}],"S":[{"t":"Dexamethasone 8 mg PO, IM or IV, then 4 mg every 6 h"}],"T":[{"t":"Supplemental oxygen titrated to SaO2 ≥ 90%; intubation and ventilation if comatose"},{"t":"Immediate descent; hyperbaric therapy if descent not possible"},{"t":"Intubated: monitor ICP and cerebral blood velocities (transcranial Doppler) if possible"}],"Co":[{"t":"Admit if ataxic or confused after descent; neurology / critical care"}]},"name":"HACE","level":"I","imp":"High-altitude cerebral edema","cond":"Emergent","act":"CBR","diet":"NPO","ecg":"stat","cxr":"portable","o2":"titrate to SaO2 ≥ 90%","sc":"کوهنورد با AMS قبلی، اکنون آتاکسی، گیجی و خواب‌آلودگی در 5000 m.","why":"نزول فوری و دگزامتازون."}],"ch":"122","name":"High-altitude cerebral edema (HACE)","name_fa":"ادم مغزی ارتفاع (HACE)","cc":["altered-mental-status","headache","environmental"],"keywords":"HACE, high altitude cerebral edema, dexamethasone, ataxia, descent, ادم مغز ارتفاع","status":"draft","features":["تخریب عصبی پیشرونده همراه با AMS یا HAPE؛ تغییر هوشیاری، آتاکسی، استوپور و در صورت عدم درمان کما؛ علائم کانونی مثل فلج اعصاب کرانیال 3 و 6","افتراق: سکته/TIA، تومور، منژیت، انسفالیت و اختلال متابولیک؛ MRI: افزایش T2 در splenium جسم پینه‌ای؛ آزمایش برای رد علل دیگر نباید درمان را به تأخیر اندازد"],"ddx":[{"n":"Stroke / TIA |","cm":1},{"n":"Meningitis / encephalitis |","cm":1},{"n":"Tumor / metabolic disturbance |"}],"redflags":["آتاکسی، تغییر هوشیاری، کما"],"guide":"اکسیژن تکمیلی با تیتر SaO2 ≥ 90%؛ کمایی: اینتوباسیون و تهویه. نزول فوری؛ هیپرباریک اگر نزول ممکن نیست. dexamethasone 8 mg PO/IM/IV سپس 4 mg هر 6 ساعت. اینتوبه: پایش ABG و پرهیز از PaCO2 < 30 mmHg؛ پایش ICP و سرعت جریان مغزی با TCD در صورت امکان. آتاکسیک یا گیج پس از نزول: بستری.","section":"environmental","source":"Tintinalli's Emergency Medicine Manual, 8th ed., Ch. 122: High-Altitude Disorders, pp. 670–672"},"decompression-illness-dive":{"id":"decompression-illness-dive","variants":[{"id":"dci-main","o":{"I":[{"t":"CXR portable (pneumothorax, pneumomediastinum, subcutaneous air)"},{"t":"CT head / brain as indicated for neurologic symptoms (do not delay recompression)"}],"L":[{"t":"CBC (hemoconcentration), CPK, electrolytes, glucose, BUN, creatinine"}],"S":[{"t":"IV fluids (isotonic)","fl":[{"k":"ci","v":"caution in heart failure / pulmonary edema"}]},{"t":"Lidocaine 1 mg/kg IV bolus then 1 mg/min infusion (possible neuroprotection in CAGE)"}],"T":[{"t":"100% oxygen; supine position if CAGE suspected (left lateral decubitus if vomiting)"},{"t":"Rapidly arrange recompression therapy with hyperbaric oxygen (Divers Alert Network 1-919-684-9111)"},{"t":"Needle decompression or tube thoracostomy if pneumothorax from pulmonary overinflation"}],"Co":[{"t":"Hyperbaric medicine / dive medicine; transfer to chamber"}]},"name":"Decompression illness (DCS / CAGE)","level":"I","imp":"Decompression illness (DCS / cerebral arterial gas embolism)","cond":"Emergent","act":"CBR","diet":"NPO","ecg":"stat","cxr":"portable","o2":"100% oxygen (non-rebreather)","sc":"غواص ۳۵ ساله ۳۰ دقیقه پس از صعود سریع با ضعف پاها، درد شانه، سردرد و گیجی.","why":"اکسیژن 100% و اعزام فوری برای recompression."}],"ch":"123","name":"Decompression illness (DCS / cerebral arterial gas embolism)","name_fa":"بیماری رفع فشار (DCS / آمبولی گاز شریانی مغز)","cc":["environmental","altered-mental-status","joint-limb-pain"],"keywords":"decompression sickness, DCS, CAGE, arterial gas embolism, scuba diving, hyperbaric oxygen, recompression, Divers Alert Network, غواصی, بیماری رفع فشار","status":"draft","features":["قوانین گاز: Boyle (فشار و حجم معکوس)، Henry (گاز محلول ∝ فشار جزئی)، Dalton (فشار کل = جمع فشار جزئی)","DCS: غواصان هوای فشرده، کارگران caisson، خلبانان ارتفاع بالا؛ در غواص معمولاً با فراتر رفتن از حدود جدول عمق/زمان؛ از چند دقیقه تا ساعت (به‌ندرت روزها) پس از سطح؛ تشکیل بیش از حد حباب → اثر مسدودکننده حاد و التهابی تأخیری","نوع I («pain-only»): پوست لکه‌دار و درد عمقی مفصل (شانه یا زانو) که با حرکت تغییر نمی‌کند؛ نوع II («serious»): CNS (معمولاً نخاع): تنگی تنه و فلج صعودی؛ مواجهه طولانی در عمق: chokes (سرفه و هموپتیزی قلبی-ریوی) یا staggers (ورتیگو و کم‌شنوایی)","CAGE: بارو‌تروما حین صعود (پارگی ریه با پنوموموتوراکس/پنومومدیاستن/آمفیزم)؛ علائم عصبی حین صعود یا بلافاصله پس از سطح: کاهش هوشیاری، تشنج، کوری، آشفتگی، همی‌پلژی یا علائم سکته؛ چون DCS و CAGE گاهی قابل‌تفکیک نیستند، اصطلاح «decompression illness»","تشخیص: پروفایل غواصی (عمق، مدت، تکرار) و زمان شروع؛ CXR: پنومومدیاستن، پنوموتوراکس، آمفیزم زیرجلدی؛ آزمایش: هماتوکریت بالا (هموکونسانتراسیون) و CPK بالا؛ افتراق: کشیدگی مفصل، دیسک گردن، ایسکمی قلب، ادم ریوی غوطه‌وری، تشنج اکسیژن (> 1.4 ATA)؛ آزمایش فشار با اکسیژن هیپرباریک معمولاً بهبود می‌دهد"],"ddx":[{"n":"Stroke / cardiac ischemia |","cm":1},{"n":"Pneumothorax |","cm":1},{"n":"Musculoskeletal strain / cervical disc |"},{"n":"Immersion pulmonary edema / oxygen toxicity seizure |"}],"redflags":["علائم عصبی پس از غواصی، کاهش هوشیاری، تشنج، پنوموموتوراکس"],"guide":"100% اکسیژن و مایع IV. CAGE مشکوک: وضعیت supine؛ در استفراغ left lateral decubitus. ترتیب سریع recompression با اکسیژن هیپرباریک (Divers Alert Network 1-919-684-9111). lidocaine 1 mg/kg IV بولوس سپس 1 mg/min ممکن است نوروپروتکشن در CAGE بدهد. overinflation ریوی حین صعود: سوزن‌گذاری یا chest tube در پنوموتوراکس.","section":"environmental","source":"Tintinalli's Emergency Medicine Manual, 8th ed., Ch. 123: Dysbarism and Complications of Diving, pp. 673–674"},"barotrauma-diving-ear-sinus":{"id":"barotrauma-diving-ear-sinus","variants":[{"id":"barotrauma-middle-ear","o":{"T":[{"t":"Decongestants and analgesics; antibiotics if infection suspected"},{"t":"Advise against diving until healing completed"}],"Co":[{"t":"ENT follow-up"}]},"name":"Middle ear / sinus barotrauma","level":"III","imp":"Diving barotrauma (middle ear / sinus)","cond":"Urgent","act":"CBR","diet":"PO","ecg":"none","cxr":"none","sc":"غواص با درد گوش، کاهش شنوایی هدایتی و خونریزی پرده تمپان پس از نزول.","why":"حمایتی؛ منع غواصی."},{"id":"barotrauma-inner-ear","o":{"T":[{"t":"Bed rest with head upright; fistula test as diagnostic aid"},{"t":"Rule out decompression illness (hyperbaric consult if neurologic features)"}],"Co":[{"t":"Otolaryngology evaluation for possible surgical exploration"}]},"name":"Inner ear barotrauma","level":"II","imp":"Inner ear barotrauma (diving)","cond":"Urgent","act":"CBR","diet":"NPO","ecg":"none","cxr":"none","sc":"غواص پس از Valsalva شدید با ورتیگو، وزوز و کم‌شنوایی حسی-عصبی.","why":"استراحت با سر بالا و ENT اورژانس."}],"ch":"123","name":"Diving barotrauma (middle ear squeeze, inner ear, sinus)","name_fa":"بارو‌تروما در غواصی (گوش میانی، گوش داخلی، سینوس)","cc":["ent","dizziness-vertigo","environmental"],"keywords":"barotitis media, middle ear squeeze, inner ear barotrauma, alternobaric vertigo, reverse squeeze, perilymph fistula, sinus barotrauma, بارو تروما, غواصی","status":"draft","features":["شایع‌ترین آسیب غواصی؛ squeeze گوش میانی (barotitis media) هنگام نزول: عدم برابری فشار → خونریزی/پارگی پرده تمپان و کم‌شنوایی هدایتی؛ Valsalva شدید → بارو‌تروما گوش داخلی با پارگی پنجره گرد یا بیضی: وزوز، کم‌شنوایی حسی-عصبی و ورتیگو","انسداد ostia سینوس در نزول: خونریزی از ماگزیلاری یا فرونتال با درد و اپیستاکسی","صعود: انبساط گاز؛ alternobaric vertigo (تفاوت فشار نامتقارن گوش میانی)؛ «reverse squeeze» نادر (گوش یا سینوس)","fistula test: دمیدن در پرده تمپان طرف مبتلا و انحراف چشم‌ها به سمت مقابل ← کمک به تشخیص بارو‌تروما گوش داخلی"],"ddx":[{"n":"Decompression illness (inner ear DCS) |","cm":1},{"n":"Otitis media / labyrinthitis |"}],"redflags":["ورتیگو و کم‌شنوایی حسی-عصبی (گوش داخلی)، علائم عصبی (DCI)"],"guide":"بارو‌تروما گوش میانی: ضداحتقان و مسکن؛ آنتی‌بیوتیک اگر عفونت مشکوک؛ ممنوعیت غواصی تا بهبودی. بارو‌تروما گوش داخلی: استراحت با سر بالا تا ارزیابی ENT برای احتمال اکتشاف جراحی.","section":"environmental","source":"Tintinalli's Emergency Medicine Manual, 8th ed., Ch. 123: Dysbarism and Complications of Diving, pp. 673–674"},"drowning-submersion":{"id":"drowning-submersion","variants":[{"id":"drowning-asymptomatic","o":{"I":[{"t":"CXR PA (often normal in asymptomatic patient); cervical spine imaging only if diving history or trauma"}],"L":[{"t":"(usually not indicated if asymptomatic)"}],"T":[{"t":"Monitor oxygen saturation; observe 4–6 hours; measure core temperature"},{"t":"If SaO2 < 95% or abnormal pulmonary examination, manage as GCS < 13"}],"Co":[{"t":"Discharge home if SaO2 and pulmonary examination normal after observation"}]},"name":"Submersion, GCS ≥ 13 and SaO2 ≥ 95% (observe 4–6 h)","level":"III","imp":"Drowning (submersion), asymptomatic","cond":"Urgent","act":"CBR","diet":"PO","ecg":"stat","cxr":"PA","o2":"if SpO2 < 95%","sc":"کودک ۸ ساله پس از افتادن در استخر و نجات سریع؛ سرفه گذرا، هوشیار، SpO2 98%.","why":"مشاهده 4 تا 6 ساعت؛ سطح اکسیژن و معاینه ریه."},{"id":"drowning-severe","o":{"I":[{"t":"CXR portable"},{"t":"CT head / C-spine only if diving history or associated trauma"}],"L":[{"t":"CBC, electrolytes, glucose, troponin I, PT/PTT, urinalysis, CK, urine myoglobin, urine drug screen; arterial blood gas (acid–base)"}],"S":[{"t":"IV fluids for hypovolemia as needed ; dextrose for hypoglycemia","fl":[{"k":"ci","v":"caution in heart failure / pulmonary edema"}]}],"T":[{"t":"ABC; oxygen to SaO2 ≥ 95%; endotracheal intubation and positive-pressure ventilation (CPAP, PEEP) as needed"},{"t":"Measure core temperature; treat hypothermia (cold-water submersion cardiac arrest: prolonged aggressive resuscitation until normothermic or not viable)"},{"t":"Treat associated injury or condition (seizure, MI, hypoglycemia)","fl":[{"k":"ci","v":"no routine antibiotic prophylaxis; no benefit from mannitol, diuretics, hypertonic saline, fluid restriction, hyperventilation, barbiturate coma or ICP monitoring"}]},{"t":"Monitor acid–base status, temperature, volume status"}],"Co":[{"t":"Admit ICU or transfer to facility with inpatient / ICU monitoring"}]},"name":"Submersion with GCS < 13, SaO2 < 95%, respiratory distress or hypothermia","level":"I","imp":"Drowning with respiratory failure / altered consciousness","cond":"Emergent","act":"CBR","diet":"NPO","ecg":"stat","cxr":"portable","o2":"supplemental oxygen to keep SaO2 ≥ 95%","sc":"مرد ۳۰ ساله یافت‌شده در رودخانه با GCS 9، رال دوطرفه، SpO2 82% و دمای 33°C.","why":"اکسیژن، تهویه فشار مثبت، گرم کردن و بستری."}],"ch":"124","name":"Drowning (submersion injury)","name_fa":"غرق‌شدگی","cc":["environmental","dyspnea","altered-mental-status"],"keywords":"drowning, near drowning, submersion, aspiration, hypothermia, cervical spine, غرق شدگی, خفگی در آب","status":"draft","features":["غرق‌شدگی: غوطه‌وری در مایع با دیسترس یا نارسایی تنفسی؛ پیش‌آگهی وابسته به آسیب ریه و CNS و نجات و احیای زودهنگام؛ پیشگیری مهم‌ترین","تا 20% بدون آسپیراسیون آب (آسیب از آسفیکسی)؛ آسپیراسیون: شستشوی surfactant ← کاهش تبادل گاز، آتلکتازی، عدم تطابق V/Q، هیپوکسی؛ آسپیراسیون متوسط تا شدید: ادم ریوی غیرقلبی؛ معاینه متغیر: ریه تمیز یا رال/رونکای/ویزینگ؛ هوشیاری طبیعی تا کما؛ خطر هیپوترمی حتی در «آب گرم»","آسیب‌های همراه (مغز و نخاع) و علل زمینه‌ای: سنکوپ، تشنج، هیپوگلیسمی، MI یا دیسریتمی؛ اسیدوز تنفسی زودهنگام و بعد متابولیک؛ اختلال الکترولیت زودرس غیرمعمول؛ CXR اغلب طبیعی در بیمار بدون علامت؛ بدون شرح غواصی یا تروما، ایمبیلیزاسیون گردن روتین و CT مغز لازم نیست"],"ddx":[{"n":"Cervical spine / head injury |","cm":1},{"n":"Syncope / seizure / MI / hypoglycemia as precipitant |","cm":1},{"n":"Hypothermia |"}],"redflags":["GCS < 13، SaO2 < 95%، رال/ویزینگ/رتراکشن، هیپوترمی، ایست"],"guide":"الگوریتم (شکل 124-1): قبل از بیمارستان: نجات سریع و محتاط؛ احتیاط C-spine در صورت شک؛ CPR؛ انتقال و اکسیژن همه. ED: ABC؛ GCS؛ درمان آسیب/وضعیت همراه (هیپوولمی، هیپوترمی، تشنج، MI). GCS ≥ 13 و SaO2 ≥ 95%: پاک‌سازی C-spine، پایش SaO2، آزمایش ancillary معمولاً لازم نیست؛ مشاهده 4 تا 6 ساعت؛ اگر SaO2 و معاینه ریه طبیعی ترخیص؛ اگر SaO2 < 95% یا معاینه غیرطبیعی مثل GCS < 13. GCS < 13 یا SaO2 < 95%: پاک‌سازی C-spine، اکسیژن برای SaO2 ≥ 95%، اینتوباسیون و تهویه فشار مثبت (CPAP، PEEP) در صورت نیاز؛ CXR، CBC، الکترولیت، گلوکز، troponin I، PT/PTT، UA، CK، میوگلوبین ادرار، غربالگری دارو؛ پایش اسید-باز، دما و حجم؛ بستری/ICU. دمای مرکزی اندازه‌گیری و هیپوترمی درمان؛ ایست در غرق آب سرد: احیای طولانی و تهاجمی تا نورموترمی یا غیرقابل‌زنده‌ماندن. پروفیلاکسی آنتی‌بیوتیک روتین ندارد. «brain resuscitation» (mannitol، دیورتیک، سالین هایپرتونیک، محدودیت مایع، هایپرونتیلاسیون، هیپوترمی کنترل‌شده، باربیتورات، ICP) فایده نشان نداده. ایست/آسیستول پس از غرق آب گرم در بیمار نورموترمیک: پیش‌آگهی ضعیف.","section":"environmental","source":"Tintinalli's Emergency Medicine Manual, 8th ed., Ch. 124: Near Drowning, pp. 675–677"},"thermal-burn":{"id":"thermal-burn","variants":[{"id":"burn-minor","o":{"L":[{"t":"(CBC / BUN / Cr / electrolytes per fixed block; no additional labs)"}],"T":[{"t":"Appropriate analgesics before burn care and for outpatient use"},{"t":"Cleanse with mild soap and water or dilute antiseptic; debride as needed"},{"t":"Topical antimicrobial: 1% silver sulfadiazine cream (not on face or in sulfa allergy), bacitracin ointment, or triple-antibiotic ointment; consider synthetic occlusive dressings"},{"t":"Cool compresses for small burns; update tetanus prophylaxis"}],"Co":[{"t":"Discharge with detailed burn care instructions and follow-up in 24–48 h"}]},"name":"Minor burn (outpatient, ABA minor criteria)","level":"III","imp":"Thermal burn, minor","cond":"Urgent","act":"CBR","diet":"PO","ecg":"none","cxr":"none","sc":"زنی ۳۰ ساله با سوختگی آب داغ 5% BSA ضخامت جزئی روی ساعد؛ سایر اندام‌ها سالم.","why":"مراقبت زخم و ترخیص با پیگیری 24 تا 48 ساعت."},{"id":"burn-major","o":{"I":[{"t":"CXR portable"},{"t":"Imaging for associated trauma per trauma guidelines"}],"L":[{"t":"Arterial blood gas, carboxyhemoglobin level; lactate; electrolytes, creatinine, CK, urinalysis (myoglobin), type and screen; troponin / ECG if electrical or smoke exposure; cyanide considered in nitrogen-containing polymer fires"}],"S":[{"t":"Lactated Ringer's per Parkland formula: adult 4 mL × weight (kg) × %BSA (partial and full thickness) over 24 h — half over first 8 h from time of burn, remainder over next 16 h (e.g., 70 kg, 40% BSA: 11,200 mL); children 3 mL × kg × %BSA plus maintenance; titrate to vital signs, perfusion and urine output","fl":[{"k":"note","v":"not subject to usual maintenance-fluid rule; monitor urine output with Foley"}]},{"t":"Two IV lines in unburned areas"},{"t":"IV opioid analgesia early, titrated to pain","fl":[{"k":"hi","v":""}]}],"T":[{"t":"Reevaluate airway; 100% oxygen; intubate and ventilate if airway compromise, airway burn, or respiratory distress"},{"t":"Humidified oxygen, bronchodilators, pulmonary toilet for inhalation injury; hyperbaric oxygen for severe carbon monoxide poisoning"},{"t":"Cover large burns with sterile dry sheets; avoid saline-soaked dressings (hypothermia); no empiric antibiotics or topical antimicrobials during resuscitation"},{"t":"Escharotomy for circumferential burns of neck, chest or limbs compromising breathing / circulation"},{"t":"Update tetanus prophylaxis; treat traumatic injuries per trauma guidelines"}],"Co":[{"t":"Burn center / burn surgery (ABA referral criteria); admit moderate and major burns"},{"t":"Trauma surgery if associated injuries"}]},"name":"Moderate–major burn (> 15–25% BSA, inhalation injury, hands/face/perineum) — resuscitation and burn center","level":"I","imp":"Thermal burn, moderate to major","cond":"Emergent","act":"CBR","diet":"NPO","ecg":"stat","cxr":"portable","o2":"100% oxygen","sc":"مرد ۴۵ ساله ۷۰ kg پس از آتش‌سوزی خانه با سوختگی 40% BSA، موی سوخته بینی، گرفتگی صدا و سوختگی دست‌ها.","why":"راه هوایی زودهنگام، Parkland و انتقال به مرکز سوختگی."}],"ch":"125","name":"Thermal burns","name_fa":"سوختگی حرارتی","cc":["burn-electrical","trauma-major"],"keywords":"thermal burn, burn, scald, Parkland formula, rule of nines, Lund and Browder, silver sulfadiazine, escarotomy, inhalation injury, burn center, سوختگی, پارکلند","status":"draft","features":["اغلب سرپایی؛ از بستری‌ها > 60% در مراکز سوختگی؛ خطر مرگ: سوختگی بزرگ‌تر، سن بالا، آسیب استنشاقی همراه و جنس مؤنث","اندازه: درصد BSA با قانون نه‌ها (Rule of Nines)؛ دقیق‌تر (به‌ویژه کودک): Lund and Browder؛ سوختگی کوچک: کف دست بیمار ≈ 1% BSA","عمق (جدول 125-1): سطحی (درجه 1): اپیدرم، بدون تاول، دردناک (آفتاب‌سوختگی، 7 روز)؛ ضخامت جزئی سطحی: اپیدرم و درم سطحی، تاول، بسیار دردناک (آب داغ، 14 تا 21 روز بدون اسکار)؛ ضخامت جزئی عمیق: درم عمیق، غدد عرق و فولیکول مو، تاول (مایع داغ، بخار، گریس، شعله؛ 3 تا 8 هفته با اسکار دائمی)؛ تمام‌ضخامت (درجه 3): اپیدرم و درم کامل سوخته، رنگ‌پریده، چرمی، بی‌درد (ماه‌ها، اسکار شدید، گرافت)؛ درجه 4: تا استخوان، چربی و/یا عضله (ماه‌ها، جراحی‌های متعدد)","آسیب استنشاقی: شایع در آتش فضای بسته و کاهش شناخت (مسمومیت، اوردوز، ضربه سر)؛ آسیب راه هوایی فوقانی و تحتانی با حرارت، ذرات و گازهای سمی؛ نشانه‌ها: سوختگی صورت، موی سوخته بینی، دوده راه هوایی فوقانی، گرفتگی صدا، خلط کربنی، ویزینگ؛ مسمومیت CO در همه آسیب استنشاقی؛ سیانید در آتش پلیمرهای نیتروژن‌دار (پشم، ابریشم، پلی‌یورتان، وینیل)","ABA (جدول 125-2): بزرگ: ضخامت جزئی > 25% BSA (10 تا 50 سال) یا > 20% (< 10 یا > 50 سال)؛ تمام‌ضخامت > 10% در هر سن؛ دست، صورت، پا یا پرینه؛ عبور از مفصل بزرگ؛ دورتادور اندام؛ آسیب استنشاقی؛ سوختگی الکتریکی؛ شکستگی/تروما؛ بیماران پرخطر ← مرکز سوختگی؛ متوسط: ضخامت جزئی 15 تا 25% (10 تا 50 سال) یا 10 تا 20% (< 10 یا > 50 سال)، تمام‌ضخامت ≤ 10% بدون ویژگی بزرگ ← بستری؛ خفیف: ضخامت جزئی < 15% (یا < 10% در سن‌های حدی)، تمام‌ضخامت < 2%، بدون ویژگی بزرگ ← سرپایی"],"ddx":[{"n":"Inhalation injury / CO / cyanide |","cm":1},{"n":"Associated trauma |","cm":1},{"n":"Toxic epidermal necrolysis / SSSS (blistering) |"},{"n":"Child abuse (scald patterns) |"}],"redflags":["سوختگی صورت/راه هوایی، گرفتگی صدا، سوختگی دورتادور، > 20 تا 25% BSA، سوختگی الکتریکی/شیمیایی"],"guide":"مرحله‌ها: پیش از بیمارستان (توقف سوختن، راه هوایی، مایع، تسکین درد، محافظت زخم)، احیا و تثبیت ED، انتقال به مرکز سوختگی. ED: ارزیابی مجدد راه هوایی، O2 100%، اینتوباسیون در علائم تهدید راه هوایی، سوختگی راه هوایی یا دیسترس تنفسی؛ ABG، سطح COHb و CXR؛ پایش علائم حیاتی و SpO2. دو IV در ناحیه سالم. فرمول Parkland/Baxter (جدول 125-3): بزرگسال: LR 4 mL × وزن (kg) × %BSA (ضخامت جزئی و تمام‌ضخامت) در 24 ساعت: نیمی در 8 ساعت اول از زمان سوختگی و نیم دیگر در 16 ساعت بعد (مثال: 70 kg با 40%: 11,200 mL)؛ کودک: LR 3 mL × وزن × %BSA + نگهدارنده؛ ادامه بر اساس علائم حیاتی، پرفیوژن و برون‌ده ادراری. درمان تروما طبق راهنماها. مراقبت زخم: کمپرس خنک روی سوختگی کوچک؛ سوختگی بزرگ با ملحفه خشک استریل (پانسمان سالین خیس هیپوترمی می‌دهد). آنتی‌بیوتیک تجربی و ضدمیکروب موضعی حین احیا توصیه نمی‌شود. اوپیوئید IV زود و تیتر بر اساس درد. آسیب استنشاقی: اکسیژن مرطوب، اینتوباسیون و تهویه، برونکودیلاتور و pulmonary toilet؛ CO شدید: اکسیژن هیپرباریک. سوختگی دورتادور گردن/قفسه/اندام: escharotomy. کزاز. بستری برای متوسط و بزرگ؛ معیارهای ارجاع ABA (جدول 125-4): تمام‌ضخامت در هر سن، الکتریکی/رعد، شیمیایی، استنشاقی، بیماری زمینه‌ای، تروما همزمان، کودک در مرکز بدون امکانات، نیاز به حمایت اجتماعی/توانبخشی، سن < 10 و > 50. سوختگی خفیف (جدول 125-5): مسکن قبل مراقبت و برای سرپایی، شستشو با صابون ملایم و آب یا آنتی‌سپتیک رقیق، دبریدمان، ضدمیکروب موضعی (silver sulfadiazine 1% (نه روی صورت یا آلرژی سولفا)، bacitracin یا triple-antibiotic)، پانسمان occlusive سنتتیک، آموزش و پیگیری 24 تا 48 ساعت.","section":"environmental","source":"Tintinalli's Emergency Medicine Manual, 8th ed., Ch. 125: Thermal and Chemical Burns, pp. 678–685"},"chemical-burn":{"id":"chemical-burn","variants":[{"id":"chemical-skin","o":{"L":[{"t":"Serum electrolytes and renal function (oxalic acid, HF: calcium, magnesium); ECG / cardiac monitoring for serious dermal HF or oxalic exposure"}],"S":[{"t":"IV fluid resuscitation and analgesia after decontamination; treat systemic toxicity as needed"},{"t":"HF skin burn: calcium gluconate gel 25 mL of 10% in 75 mL water-soluble lubricant; dermal injection of 10% calcium gluconate 0.5 mL/cm² (small-gauge needle); arterial infusion over 4 h (40 mL D5W + 10 mL of 10% calcium gluconate); consider IV calcium and magnesium"},{"t":"Oxalic acid: IV calcium may be required"}],"T":[{"t":"Remove garments; brush off dry particles; immediate copious water irrigation (alkali: prolonged); elemental metals (sodium, lithium, calcium, magnesium): cover with mineral oil / sand / class D extinguisher, no water"},{"t":"Phenol: sponge with undiluted polyethylene glycol 200–400 (or isopropyl alcohol); white phosphorus: keep skin wet / submerged and debride particles; cement: remove particles with scrub brush; tar: cool, baby oil, polysorbate ointment; mustard: decontaminate (adsorbent powders if water limited)"},{"t":"Tetanus prophylaxis; analgesia"}],"Co":[{"t":"Burn center / burn specialist (nitric acid, HF of hands/feet/digits/nails: plastic surgery); poison center / toxicology"}]},"name":"Chemical burn, skin (decontamination, agent-specific)","level":"II","imp":"Chemical burn, skin","cond":"Emergent","act":"CBR","diet":"PO","ecg":"once","cxr":"none","sc":"کارگر با پاشیده شدن قلیا روی دست و ساعد با سوزش شدید.","why":"شستشوی فوری و طولانی؛ درمان اختصاصی عامل."},{"id":"chemical-eye","o":{"T":[{"t":"Immediate irrigation of each involved eye with 1–2 L normal saline; continue until pH normal (prolonged for alkali)","fl":[{"k":"note","v":"visual acuity check and pH testing follow, not precede, initial irrigation"}]},{"t":"Lacrimators (tear gas, pepper spray): copious irrigation"},{"t":"Analgesia"}],"Co":[{"t":"Ophthalmology consultation (urgent)"}]},"name":"Chemical eye burn (acid, alkali, lacrimator)","level":"I","imp":"Chemical eye burn","cond":"Emergent","act":"CBR","diet":"PO","ecg":"none","cxr":"none","sc":"مرد ۲۸ ساله پس از پاشیده شدن قلیای بازکننده لوله به چشم با درد شدید و تاری دید.","why":"شستشوی فوری قبل از هر چیز؛ سپس pH و بینایی."}],"ch":"125","name":"Chemical burns (skin and eye)","name_fa":"سوختگی شیمیایی (پوست و چشم)","cc":["burn-electrical","eye","wound-bite"],"keywords":"chemical burn, alkali, acid, hydrofluoric acid, phenol, cement, white phosphorus, tar, mustard, tear gas, pepper spray, ocular chemical burn, سوختگی شیمیایی","status":"draft","features":["بیش از 25,000 محصول؛ درصد کوچک ولی 30% مرگ‌های سوختگی؛ بسته به عامل، غلظت، حجم، مدت و عمق نفوذ؛ قلیا معمولاً آسیب بیشتر از اسید (نکروز liquefaction عمیق‌تر؛ اسید: coagulation و escar محدودکننده)؛ HF: نفوذ سریع از پوست سالم و درد پیشرونده و تخریب عمیق بدون آسیب سطحی واضح","سمیت سیستمیک (هیپوتانسیون، اسیدوز، شوک) در جذب برخی مواد؛ سوختگی چشم اورژانس واقعی: اسید: رسوب پروتئین و قرنیه «ground glass»؛ قلیا شدیدتر و نفوذ عمیق‌تر؛ lacrimators (گاز اشک‌آور، اسپری فلفل): تحریک چشم، مخاط و ریه","تشخیص: شرح حال؛ در هر تحریک/درد پوستی فکر کن؛ pH paper برای چشم"],"ddx":[{"n":"Systemic toxicity (HF: hypocalcemia, arrhythmia) |","cm":1},{"n":"Thermal burn |"},{"n":"Contact dermatitis |"}],"redflags":["HF، سوختگی چشم، سمیت سیستمیک، اشتعال فلز/فسفر، مواجهه دهانی"],"guide":"اولویت: قطع فرآیند سوختن: لباس را خارج، ذرات خشک را پاک و فوراً شستشوی فراوان با آب؛ فلزات عنصری (سدیم، لیتیم، کلسیم، منیزیم) را با روغن معدنی بپوشان (آب واکنش گرمازا). چشم: 1 تا 2 L NS برای هر چشم؛ در اسید و قلیا تا pH طبیعی؛ قلیا شستشوی طولانی‌تر؛ بینایی و pH بعد از شستشوی اولیه؛ چشم‌پزشک. جدول 125-6: اسیدها: شستشوی فراوان؛ acetic acid: در سوختگی وسیع پوست سر آنتی‌بیوتیک سیستمیک؛ phenol: شستشو، ایزوپروپیل الکل نیز، اسفنج با PEG 200 تا 400 غلیظ؛ chromic: پایش سمیت سیستمیک؛ formic: دیالیز در سمیت شدید؛ HF: calcium gluconate تزریق داخل‌جلدی 10% یا داخل‌شریانی در شدید و ژل 25 mL از 10% در 75 mL لوبریکانت محلول در آب و پایش Ca/Mg؛ nitric: شستشو و مشاوره سوختگی؛ oxalic: الکترولیت و کلیه، Ca IV و مانیتور. قلیاها: شستشوی طولانی؛ سیمان پورتلند: برس برای ذرات؛ فلزات عنصری: آب منع در فلز مشتعل؛ پوشاندن با شن، فوم CO2/class D یا روغن معدنی؛ برش فلز غیرقابل پاک‌کردن. هیدروکربن: بنزین: دکونتامیناسیون؛ قیر: خنک کردن، baby oil، پماد آنتی‌بیوتیک با polysorbate. vesicants (خردل): دکونتامیناسیون؛ در کمبود آب پودر جاذب (آرد، talc، fuller's earth). alkyl mercury: شستشو و دبریدمان/تخلیه تاول (جیوه). lacrimators: شستشوی فراوان. white phosphorus: خارج کردن لباس، شستشو و مرطوب یا غوطه‌ور نگه داشتن تا همه ذرات خارج (اشتعال در هوا)، دبریدمان ذرات؛ airbag: شستشوی طولانی. جدول 125-7 HF پوستی: 1) شستشو 15 تا 30 دقیقه فوراً؛ 2) ژل calcium gluconate (25 mL از 10% در 75 mL)؛ 3) تزریق داخل‌جلدی calcium gluconate 10% با 0.5 mL/cm²، تزریق شریانی طی 4 ساعت (40 mL D5W + 10 mL calcium gluconate 10%)، Mg و Ca IV؛ مشاوره جراحی پلاستیک در HF دست، پا، انگشت و ناخن؛ سپس مایع IV، مسکن، کزاز و سمیت سیستمیک.","section":"environmental","source":"Tintinalli's Emergency Medicine Manual, 8th ed., Ch. 125: Thermal and Chemical Burns, pp. 678–685"},"electrical-injury":{"id":"electrical-injury","variants":[{"id":"electrical-low-voltage","o":{"L":[{"t":"(no additional labs if asymptomatic; CK if symptomatic)"}],"T":[{"t":"Dry sterile dressing for any burn; tetanus prophylaxis; superficial puncture wound care (ECD)"},{"t":"Delayed labial artery bleeding instructions if oral injury in child"}],"Co":[{"t":"Discharge: asymptomatic, low voltage (≤ 240 V), normal ECG and normal examination; children with isolated oral / hand injury after ENT / plastic surgery consultation"}]},"name":"Low-voltage (≤ 240 V) injury, asymptomatic with normal ECG; ECD (TASER) exposure","level":"III","imp":"Electrical injury, low voltage / ECD exposure","cond":"Urgent","act":"CBR","diet":"PO","ecg":"stat","cxr":"none","sc":"مرد ۳۵ ساله پس از برق‌گرفتگی 220 V خانگی بدون علامت، معاینه و ECG طبیعی؛ یا فرد پس از TASER با سوراخ سطحی.","why":"ECG و معاینه طبیعی: ترخیص؛ مراقبت زخم."},{"id":"electrical-high-voltage","o":{"I":[{"t":"CXR portable; CT head as needed for altered mental status; imaging of spine, pelvis, long bones per trauma guidelines"}],"L":[{"t":"CK, serum and urine myoglobin; electrolytes (K, Ca), BUN, creatinine; urinalysis; CBC, coagulation; troponin; blood gas; lactate; type and screen"}],"S":[{"t":"Aggressive crystalloid resuscitation with Foley urine output monitoring: target 2 mL/kg/h until CK < 5 times normal or urine myoglobin normal","fl":[{"k":"ci","v":"caution in heart failure; usual burn-resuscitation formulas often underestimate requirements"}]},{"t":"IV opioids for pain"}],"T":[{"t":"Treat as blunt multiple trauma: ACLS protocols, cervical and spine immobilization; high-flow oxygen and pulse oximetry; continuous cardiac monitoring"},{"t":"VF / asystole / VT: standard ACLS; seizures: standard therapy and consider focal cerebral injury"},{"t":"Cover burns with dry sterile dressings; tetanus prophylaxis; reduce and immobilize fractures and dislocations","fl":[{"k":"note","v":"prophylactic antibiotics not necessary unless large contaminated open wounds"}]},{"t":"Assess for compartment syndrome and need for fasciotomy"}],"Co":[{"t":"Admit for cardiac monitoring (high voltage > 600 V; symptoms; dysrhythmia / abnormal ECG; deep burns)"},{"t":"General / trauma / burn surgery (priority for compartment syndrome); obstetrics for pregnant patients (fetal monitoring); ophthalmology / ENT as indicated"}]},"name":"High-voltage (> 600 V) or symptomatic electrical injury (cardiac, neuro, rhabdomyolysis)","level":"I","imp":"Electrical injury, high voltage / symptomatic","cond":"Emergent","act":"CBR","diet":"NPO","ecg":"stat","cxr":"portable","o2":"high-flow oxygen","sc":"لاین‌من ۴۰ ساله پس از تماس با خط 10,000 V با سوختگی دست و پا، گیجی، ادرار تیره و ECG: PVC.","why":"مانند ترومای چندگانه، ECG، CK، کریستالوئید برای UOP 2 mL/kg/h و بستری."}],"ch":"126","name":"Electrical injuries (including TASER / electronic control devices)","name_fa":"آسیب‌های الکتریکی (شامل TASER)","cc":["burn-electrical","trauma-major","palpitations"],"keywords":"electrical injury, high voltage, low voltage, electrocution, rhabdomyolysis, compartment syndrome, TASER, stun gun, labial artery bleeding, برق گرفتگی, الکتریسیته","status":"draft","features":["از سوختگی سطحی تا آسیب چند‌سیستمی؛ ولتاژ پایین (≤ 1000 V) و بالا (> 1000 V)؛ مکانیسم‌ها: آسیب مستقیم انرژی الکتریکی، آسیب حرارتی، تروما (سقوط یا انقباض عضله)","فوری: دیسریتمی از جمله VF، ایست تنفسی، تشنج؛ عوارض قلبی بیشتر در ولتاژ بالا؛ از دست رفتن هوشیاری گذرا شایع؛ سوختگی شدید با خط ولتاژ بالا؛ اندازه پوست با آسیب داخلی همبسته نیست؛ تروما همراه شایع","جدول 126-1: قلب: مرگ ناگهانی (VF، آسیستول)، درد قفسه، دیسریتمی، تغییر ST-T، بلوک شاخه، آسیب میوکارد، MI (نادر)، هیپوتانسیون، هیپرتانسیون؛ عصبی: تغییر هوشیاری، آژیتاسیون، کما، تشنج، ادم مغز، آنسفالوپاتی هیپوکسیک، سردرد، آفازی، ضعف، پاراپلژی، کوادری‌پلژی، اختلال نخاع (ممکن تأخیری)، نوروپاتی؛ پوست: سوختگی تماسی، قوس و «flash»، سوختگی ثانویه؛ عروق: ترومبوز، نکروز coagulation، DIC، پارگی دیررس رگ، آنوریسم، کمپارتمان؛ ریه: ایست تنفسی، پنومونی آسپیراسیون، ادم ریوی، کوفتگی، آسیب استنشاقی؛ کلیه/متابولیک: AKI (رنگدانه هم و هیپوولمی)، میوگلوبینوری، اسیدوز لاکتیک، هیپوکالمی، هیپوکلسمی، هیپرگلیسمی؛ GI: سوراخ شدن، زخم استرس، خونریزی؛ عضله: میونکروز، کمپارتمان؛ اسکلتی: شکستگی فشاری مهره، شکستگی استخوان بلند، در رفتگی شانه (قدامی و خلفی)، شکستگی اسکاپولا؛ چشم: سوختگی قرنیه، آب مروارید تأخیری، خونریزی/ترومبوز داخل‌چشمی، uveitis، جداشدگی شبکیه؛ گوش: کم‌شنوایی، وزوز، پارگی پرده (نادر)، ماستوئیدیت/منژیت تأخیری؛ دهان: خونریزی تأخیری شریان لبیال، اسکار و بدشکلی، تأخیر گفتار؛ بارداری: سقط و مرگ جنین","تشخیص بر اساس شرح تماس و ضایعات پوستی/دهانی (کودک)؛ بیمار با فراموشی یا تغییر هوشیاری بدون ضایعه پوستی: معاینه دقیق‌تر (رعد/طوفان)؛ ECG: دیسریتمی دهلیزی/بطنی، برادی‌آریتمی، QT طولانی، ST-T؛ CK، میوگلوبین؛ آزمایش و تصویربرداری مثل تروما (ولتاژ بالا)","ECDs (cattle prod، stun gun، TASER): ولتاژ بالا/آمپر پایین: انقباض غیرارادی عضله، ناتوانی عصبی-عضلانی و درد؛ آسیب الکتریکی حداقل؛ سوراخ‌های سطحی و بریدگی/سوختگی جزئی؛ بیشتر مرگ‌ها در افراد بسیار بیمار و آژیته (سایکوز، محرک)"],"ddx":[{"n":"Myocardial ischemia / arrhythmia of other cause |","cm":1},{"n":"Head / spinal cord injury / stroke |","cm":1},{"n":"Compartment syndrome / rhabdomyolysis |"}],"redflags":["ولتاژ > 600 V، دیسریتمی، درد قفسه، تغییر هوشیاری، میوگلوبینوری، کمپارتمان، سوختگی عمیق"],"guide":"تروما بلانت چندگانه: ACLS و ایمبیلیزاسیون گردن/ستون. راه هوایی: سوختگی صورت ناشی از flash معمولاً راه هوایی را درگیر نمی‌کند؛ اکسیژن پرجریان و پالس‌اکسیمتری. VF، آسیستول، VT: ACLS استاندارد؛ سایر دیسریتمی‌ها معمولاً گذرا. تشنج بلافاصله پس از شوک؛ تشنج جدید: درمان استاندارد و بررسی آسیب کانونی مغز. کمپارتمان: مشاوره فوری جراحی عمومی/تروما/سوختگی. پایش هیپرکالمی، رابدومیولیز و AKI با Foley؛ کریستالوئید در سوختگی وسیع یا عضله آسیب‌دیده؛ فرمول‌های سوختگی معمولاً کمتر از نیاز تخمین می‌زنند؛ رابدومیولیز شدید/میوگلوبینوری: هیدراتاسیون تهاجمی با هدف UOP 2 mL/kg/h تا CK < 5 برابر نرمال یا میوگلوبین ادرار طبیعی. سوختگی با پانسمان خشک استریل؛ آنتی‌بیوتیک پروفیلاکتیک معمولاً لازم نیست مگر زخم باز آلوده وسیع. کزاز. اوپیوئید. شکستگی/در رفتگی: جا انداختن و ایمبیلیزاسیون. باردار: مشاوره زنان و پایش جنین. بستری: بیش از آسیب ولتاژ پایین خفیف (جدول 126-3): ولتاژ > 600 V؛ علائم سیستمیک (قلبی: درد قفسه و تپش؛ عصبی: LOC، گیجی، ضعف، سردرد، پارستزی؛ تنفسی: تنگی نفس؛ GI: درد شکم و استفراغ)؛ آسیب عصبی/عروقی انگشت یا اندام؛ سوختگی با آسیب زیرجلدی؛ دیسریتمی یا ECG غیرطبیعی؛ شبهه سوء قصد/سوءاستفاده/خودکشی یا وضعیت اجتماعی ناپایدار؛ بارداری؛ آسیب همراه؛ بیماری قلبی/کلیه/عصبی. کودک با آسیب دهانی یا دست منفرد: ترخیص پس از مشاوره ENT/پلاستیک؛ آموزش کنترل خونریزی دیررس شریان لبیال و پیگیری. بدون علامت با ولتاژ پایین (≤ 240 V)، ECG و معاینه طبیعی: ترخیص. ECD: ارزیابی مثل تروما بلانت/مسمومیت ناشناخته در بیمار بدحال/آژیته؛ مانیتور قلبی و آزمایش‌های دیگر فقط به‌علت TASER لازم نیست.","section":"environmental","source":"Tintinalli's Emergency Medicine Manual, 8th ed., Ch. 126: Electrical and Lightning Injuries, pp. 686–691"},"lightning-injury":{"id":"lightning-injury","variants":[{"id":"lightning-main","o":{"I":[{"t":"CXR portable; CT head / spine and trauma imaging per trauma guidelines"}],"L":[{"t":"CK, myoglobin, electrolytes, BUN, creatinine, CBC, troponin, urinalysis; coagulation; type and screen"}],"S":[{"t":"IV crystalloids","fl":[{"k":"ci","v":"caution in heart failure; hypotension should prompt search for hemorrhage"}]}],"T":[{"t":"Treat as blunt multiple trauma: ACLS protocols, cervical and spine immobilization; continuous monitoring (vital signs, rhythm, pulse oximetry); high-flow oxygen"},{"t":"Mass casualty: aggressive resuscitation of respiratory / cardiac arrest victims (ventilate until ROSC)"},{"t":"Hypertension frequent and transient: no therapy; early seizures (anoxia): standard therapy"},{"t":"Keraunoparalysis is a diagnosis of exclusion; fasciotomy only with high compartment pressure"},{"t":"Tetanus prophylaxis if burns / wounds (no prophylactic antibiotics unless organic contamination)"}],"Co":[{"t":"Admit critical care unit if persistent musculoskeletal, neurologic, cardiac rhythm or vascular abnormalities, or significant burns; general / trauma / burn surgery; ophthalmology / ENT follow-up; obstetrics for pregnant patients"},{"t":"Discharge with outpatient follow-up (delayed effects) for minor injuries with negative workup"}]},"name":"Lightning strike","level":"I","imp":"Lightning injury","cond":"Emergent","act":"CBR","diet":"NPO","ecg":"stat","cxr":"portable","o2":"high-flow oxygen","sc":"کوهنورد ۲۵ ساله پس از اصابت صاعقه با بی‌هوشی گذرا، گیجی، فراموشی، ضعف پاها، پارگی پرده تمپان و HR 120، BP 170/100.","why":"مانند تروما + ECG؛ ایست تنفسی را فوراً تهویه کن."}],"ch":"126","name":"Lightning injuries","name_fa":"آسیب صاعقه","cc":["burn-electrical","trauma-major","altered-mental-status"],"keywords":"lightning strike, lightning injury, keraunoparalysis, Lichtenberg figures, feathering burns, reverse triage, صاعقه","status":"draft","features":["جریان یک‌طرفه با ولتاژ بسیار بالا؛ اغلب روی پوست (flashover) ← بیشتر بقا؛ ولی نسبت قابل‌توجهی عوارض دائمی","اثر در چند سطح: الکتریکی، حرارت بالا و شوک‌ویو؛ شایع‌ترین علت فوری مرگ: ایست قلبی هیپوکسیک اولیه یا ثانویه ناشی از ایست تنفسی؛ هیپرتانسیون و تاکی‌کاردی (فعال‌سازی سمپاتیک)؛ از دست رفتن هوشیاری گذرا، گیجی و فراموشی؛ سوختگی «feathering» یا سرخسی پاتوگنومونیک ولی گذرا و نادر؛ پارگی پرده تمپان (blast)؛ آسیب عمیق بافتی، میوگلوبینوری و نارسایی کلیه نادر","جدول 126-4: قلب: آسیستول، VF/VT، PVC، ECG، MI (غیرمعمول)؛ عصبی (فوری یا تأخیری، گذرا یا دائمی): LOC، گیجی، فراموشی، خونریزی داخل‌جمجمه‌ای، همی‌پلژی، فلج مرکز تنفس، ادم مغز، نوریت، تشنج، سندرم پارکینسونی، انفارکت مغز، میلوپاتی، آتروفی عضلانی پیشرونده، سندرم مخچه‌ای پیشرونده، فلج گذرا، پارستزی، اختلال اتونوم؛ پوست: سوختگی (درجه 1 تا 3)، اسکار، کنتراکچر؛ چشم: آب مروارید (اغلب تأخیری)، ضایعات قرنیه، uveitis، iridocyclitis، خونریزی ویتره، دژنراسیون ماکولا، آتروفی عصب بینایی، دوبینی، chorioretinitis، جداشدن شبکیه، hyphema؛ گوش: پارگی پرده، کم‌شنوایی موقت یا دائم، وزوز، آتاکسی، ورتیگو، نیستاگموس؛ کلیه: میوگلوبینوری، هموگلوبینوری، نارسایی نادر؛ بارداری: مرگ جنین، جدا شدن جفت؛ متفرقه: تروما بلانت ثانویه، کمپارتمان، DIC","تشخیص بر اساس شرح؛ در هر بیمار بدحال یافت‌شده بیرون حین یا پس از طوفان؛ مواجهه داخل ساختمان (استخر، تلفن سیمی، سازه ضعیف) نادر؛ ارزیابی دقیق عصبی، قلبی-عروقی، گوش، چشم و تروما؛ آزمایش و تصویربرداری مثل تروما؛ افتراق: سکته/خونریزی داخل‌جمجمه‌ای، صرع، تروما به مغز/نخاع"],"ddx":[{"n":"Stroke / intracranial hemorrhage |","cm":1},{"n":"Blunt trauma / spinal cord injury |","cm":1},{"n":"Seizure disorder |"}],"redflags":["ایست تنفسی/قلبی، تغییر هوشیاری، هیپوتانسیون (به خونریزی فکر کن)، حاملگی"],"guide":"تروما بلانت چندگانه: ACLS و ایمبیلیزاسیون ستون. در حوادث با تلفات انبوه برخلاف تریاژ معمول، احیای تهاجمی برای بیماران با ایست تنفسی و قلبی (reverse triage)؛ ایست تنفسی ممکن است از ایست قلبی طولانی‌تر باشد و تهویه کافی از آسیب هیپوکسیک تا ROSC پیشگیری می‌کند. دیسریتمی طبق ACLS. پایش مداوم علائم حیاتی، ریتم و SpO2؛ اکسیژن پرجریان و کریستالوئید IV. هیپرتانسیون شایع و گذرا و اندیکاسیون درمان نیست؛ هیپوتانسیون غیرمنتظره: بررسی خونریزی. تشنج زودرس احتمالاً آنوکسی؛ پایدار: درمان استاندارد و بررسی آسیب کانونی. keraunoparalysis (ضعف گذرا اندام) تشخیص حذفی: سایر علل پارزی ناشی از تروما را بررسی کن. اندام بدون نبض: فاسیوتومی فقط با فشار کمپارتمان بالا. کزاز؛ آنتی‌بیوتیک پروفیلاکتیک فقط با آلودگی ارگانیک. بستری ICU: علائم عضلانی-اسکلتی پایدار، اختلال عصبی، ریتم قلبی یا عروقی، یا سوختگی قابل‌توجه؛ مشاوره جراحی؛ باردار: مشاوره زنان و پایش جنین. آسیب خفیف با ورک‌آپ منفی: ترخیص و پیگیری سرپایی برای اثرات تأخیری.","section":"environmental","source":"Tintinalli's Emergency Medicine Manual, 8th ed., Ch. 126: Electrical and Lightning Injuries, pp. 686–691"},"carbon-monoxide-poisoning":{"id":"carbon-monoxide-poisoning","variants":[{"id":"co-mild","o":{"L":[{"t":"Carboxyhemoglobin level by blood co-oximetry (pulse oximetry unreliable); lactate, electrolytes (anion gap); troponin if chest pain / ECG changes; pregnancy test in women of childbearing age"}],"T":[{"t":"100% oxygen by facemask with reservoir until asymptomatic; continuous monitoring of vital signs, heart rate and rhythm"},{"t":"Observe 4 h; ensure home / work environment no longer a source of CO"}],"Co":[{"t":"Discharge home after symptom resolution with safety assessment"}]},"name":"Mild CO exposure (headache, nausea; no neuro / cardiac features)","level":"III","imp":"Carbon monoxide poisoning, mild","cond":"Urgent","act":"CBR","diet":"PO","ecg":"stat","cxr":"none","o2":"100% oxygen via non-rebreather mask until asymptomatic","sc":"خانواده‌ای با سردرد و تهوع پس از روشن کردن بخاری گازی؛ هوشیار، ECG طبیعی، COHb 12%.","why":"اکسیژن 100%، مشاهده 4 ساعت و بررسی ایمنی خانه."},{"id":"co-severe","o":{"I":[{"t":"CXR portable"},{"t":"CT / MRI brain if focal neurologic findings (globus pallidus lesions) as indicated"}],"L":[{"t":"COHb by co-oximetry; arterial blood gas (anion gap acidosis), lactate; troponin, CK; electrolytes, BUN, creatinine; glucose; pregnancy test; cyanide considered in smoke inhalation"}],"S":[{"t":"IV access; isotonic fluid as needed","fl":[{"k":"ci","v":"caution in heart failure / pulmonary edema"}]}],"T":[{"t":"100% oxygen by facemask with reservoir until asymptomatic; secure airway and stable hemodynamics before transport to HBO"},{"t":"Continuous cardiac monitoring (ECG ischemia / dysrhythmias); benzodiazepine for seizures"}],"Co":[{"t":"Hyperbaric specialist consultation for HBO (syncope, confusion/AMS, seizure, coma, focal deficit, ischemia, COHb > 25%, pregnancy with COHb > 15%)"},{"t":"Hospitalize; cardiology if ischemia; toxicology / poison center"}]},"name":"Moderate–severe CO poisoning (syncope, AMS, seizure, chest pain, ECG changes, COHb > 25%, pregnancy with > 15%)","level":"I","imp":"Carbon monoxide poisoning, severe","cond":"Emergent","act":"CBR","diet":"NPO","ecg":"stat","cxr":"portable","o2":"100% oxygen via non-rebreather mask","sc":"مردی ۵۰ ساله یافت‌شده بی‌هوش در گاراژ با موتور روشن؛ تشنج، COHb 34% و ST depression.","why":"اکسیژن 100% و انتقال برای HBO پس از ایمن‌سازی راه هوایی."}],"ch":"127","name":"Carbon monoxide poisoning","name_fa":"مسمومیت با مونوکسید کربن","cc":["poisoning","headache","altered-mental-status","dyspnea"],"keywords":"carbon monoxide, CO poisoning, carboxyhemoglobin, COHb, hyperbaric oxygen, HBO, smoke inhalation, methylene chloride, مونوکسید کربن, هیپرباریک","status":"draft","features":["گاز بی‌رنگ، بی‌بو و غیرتحریکی که اکسیژن را از هموگلوبین جابه‌جا می‌کند ← هیپوکسی بافتی زودرس و آسیب عصبی تأخیری؛ منابع: احتراق ناقص هر سوخت کربنی (بنزین، نفت سفید، گاز طبیعی، زغال) یا متابولیسم methylene chloride استنشاقی","شک: مواجهه با موتور/بخاری گازی یا پروپان، استنشاق دود یا چند قربانی با تغییر هوشیاری، اسیدوز یا کما","بسیار متغیر؛ اثر هیپوکسی بر قلب-عروق و عصب (جدول 127-1): سردرد، اختلال بینایی، استفراغ، گیجی، آتاکسی، تنگی نفس/تاکی‌پنه، تشنج، تغییر ECG ایسکمیک و/یا دیسریتمی، سنکوپ، خونریزی شبکیه، درد قفسه، ضایعات تاولی پوست، نقص عصبی کانونی؛ از «شبه‌آنفلوانزا» تا کما؛ لب «cherry red» به‌ندرت در بیمار زنده؛ پیامد طولانی عصبی/شناختی","تشخیص: co-oximetry خون مطمئن‌ترین؛ COHb تأیید مواجهه ولی همبسته با علائم یا پیش‌آگهی نیست؛ پایه تا 5% در غیرسیگاری و 10% در سیگاری؛ پالس‌اکسیمتری معمول غیرقابل‌اعتماد (SpO2 کاذب نرمال/بالا)؛ علائم‌دار: اسیدوز متابولیک anion gap، لاکتات بالا، CPK، troponin، ECG ایسکمیک و ضایعات دوطرفه globus pallidus در تصویربرداری مغز","افتراق: بیماری شبه‌آنفلوانزا، گاستروانتریت، مسمومیت‌های دیگر، علل عفونی تغییر هوشیاری؛ اختلال قلبی-عروقی پس از مسمومیت ممکن MI همزمان باشد"],"ddx":[{"n":"Cyanide poisoning (fires) |","cm":1},{"n":"Acute coronary syndrome |","cm":1},{"n":"Flu-like illness / gastroenteritis |"},{"n":"Other toxic exposure / CNS infection |"}],"redflags":["سنکوپ، گیجی، تشنج، کما، نقص کانونی، ایسکمی میوکارد، COHb > 25%، بارداری با COHb > 15%"],"guide":"خارج کردن از منبع و ABC. در همه مشکوکان بیشترین غلظت اکسیژن موجود (100% با ماسک ذخیره‌دار) تا بدون علامت شدن؛ پایش مداوم علائم حیاتی و ریتم؛ IV. اندیکاسیون HBO (جدول 127-2): سنکوپ، گیجی/تغییر هوشیاری، تشنج، کما، نقص کانونی، بارداری با COHb > 15%، COHb > 25% در هر بیمار، شواهد ایسکمی حاد میوکارد؛ اندیکاسیون کودک و بزرگسال مشابه؛ آستانه COHb در باردار کمتر؛ مشاوره متخصص هیپرباریک؛ راه هوایی ایمن و همودینامیک پایدار قبل از انتقال. ترخیص (جدول 127-3): حداقل/بدون علامت: خانه با بررسی ایمنی؛ سردرد: اکسیژن 100% در ED و خانه پس از رفع علائم؛ استفراغ، سطح CO بالا، آتاکسی، تشنج، سنکوپ، درد قفسه، نقص کانونی، تنگی نفس، تغییر ECG: بستری و اکسیژن 100% در ED، مشورت هیپرباریک (سطح CO، بیماری همراه از جمله بارداری، سن و پایداری در تصمیم انتقال)؛ مشاهده 4 ساعت. اطمینان از رفع منبع در خانه/کار.","section":"environmental","source":"Tintinalli's Emergency Medicine Manual, 8th ed., Ch. 127: Carbon Monoxide, pp. 692–694"},"mushroom-poisoning":{"id":"mushroom-poisoning","variants":[{"id":"mushroom-early-gi","o":{"L":[{"t":"(electrolytes, glucose as per fixed block); liver enzymes and coagulation if time course uncertain"}],"S":[{"t":"IV hydration (isotonic)","fl":[{"k":"ci","v":"caution in AKI, heart failure / pulmonary edema"}]}],"T":[{"t":"Antiemetics (e.g., ondansetron)"},{"t":"Poison center consultation; identify mushroom type and time to onset (observe for delayed toxicity)"}],"Co":[{"t":"Discharge when symptoms subside if early onset (< 2 h) and course reassuring; admit if delayed onset"}]},"name":"Early-onset (< 2 h) GI mushroom poisoning","level":"III","imp":"Mushroom poisoning, early-onset GI","cond":"Urgent","act":"CBR","diet":"NPO","ecg":"once","cxr":"none","sc":"مردی ۴۰ ساله 1 ساعت پس از خوردن قارچ وحشی با تهوع، استفراغ و اسهال؛ علائم حیاتی پایدار.","why":"مایع و ضداستفراغ؛ مراقب نوع تأخیری باش."},{"id":"mushroom-amatoxin-delayed","o":{"L":[{"t":"AST, ALT, bilirubin, PT/INR (coagulation), glucose, electrolytes, BUN, creatinine, CBC (hemolysis); monitored serially"}],"S":[{"t":"IV hydration; closely monitor electrolytes, glucose, renal and hepatic function"},{"t":"Acetylcysteine loading 140 mg/kg PO/NG"},{"t":"Penicillin G 300,000 to 1,000,000 U/kg IV per day"},{"t":"Silymarin 5 mg/kg IV over 1 h, then 20 mg/kg IV per day"}],"T":[{"t":"Gyromitra: benzodiazepines for seizures AND pyridoxine 5 g IV"},{"t":"Antiemetics; supportive care"}],"Co":[{"t":"Admit all delayed-onset patients for 48 h monitoring (renal and hepatic function, fluid status)"},{"t":"Early transfer to liver transplant center if rapid progression to hepatic encephalopathy, hepatorenal syndrome, or coagulopathy; toxicology / poison center"}]},"name":"Delayed-onset (6–24 h) mushroom poisoning — amatoxin (Amanita / Lepiota) / Gyromitra / A. smithiana","level":"I","imp":"Mushroom poisoning, delayed onset (risk of hepatic / renal failure)","cond":"Emergent","act":"CBR","diet":"NPO","ecg":"once","cxr":"none","sc":"زنی ۳۵ ساله 10 ساعت پس از خوردن قارچ شبیه Amanita با استفراغ شدید، اسهال و ضعف.","why":"شروع NAC/پنی‌سیلین/silymarin و پایش کبد؛ بستری 48 ساعت."},{"id":"mushroom-neuro-muscarinic","o":{"L":[{"t":"Glucose; electrolytes; CK if agitated"}],"S":[{"t":"IV hydration (disulfiram-like reaction)"}],"T":[{"t":"Muscarinic (SLUDGE): supportive; atropine 0.01 mg/kg IV repeated as needed for severe distress / secretions"},{"t":"CNS excitement / hallucinogenic: supportive; diazepam 2–5 mg IV as needed for adults"},{"t":"Disulfiram-like (Coprinus): supportive and IV hydration"}],"Co":[{"t":"Discharge when symptoms subside (hallucinogenic or muscarinic only); poison center"}]},"name":"Muscarinic / anticholinergic CNS / hallucinogenic / disulfiram-like mushroom syndromes","level":"III","imp":"Mushroom poisoning, neurologic / muscarinic / disulfiram-like syndrome","cond":"Urgent","act":"CBR","diet":"NPO","ecg":"stat","cxr":"none","sc":"جوانی ۲۰ ساله پس از خوردن قارچ جادویی با توهم و آتاکسی؛ یا فردی با تعریق و ترشحات پس از Inocybe.","why":"حمایتی؛ آتروپین فقط در موسکارینی شدید؛ دیازپام برای هیجان."}],"ch":"128","name":"Mushroom poisoning","name_fa":"مسمومیت با قارچ","cc":["poisoning","nausea-vomiting","abdominal-pain","diarrhea"],"keywords":"mushroom poisoning, Amanita phalloides, amatoxin, Gyromitra, Inocybe, muscarinic, psilocybin, Coprinus, N-acetylcysteine, silymarin, penicillin G, liver transplant, قارچ, آمانیتا","status":"draft","features":["چهار گروه: جمع‌کنندگان مواد غذایی، نوجوانان/جوانان برای «high» شدن، کودکان پیش‌دبستانی حین بازی بیرون و (نادر) سوء قصد/خودکشی","شروع زودرس: ≤ 2 ساعت؛ تأخیری: 6 ساعت تا 20 روز؛ تعیین یک یا چند نوع قارچ و فاصله تا علائم؛ توصیف قارچ از جمع‌کننده","بیشتر بیماران با علائم GI ≤ 2 ساعت سیر مطمئن دارند؛ استثنا: Amanita smithiana (GI زودرس و نارسایی کلیه تأخیری)؛ قارچ‌های با اثر کبد، کلیه و CNS معمولاً استفراغ ≥ 6 ساعت تأخیر؛ گونه‌های سمی: Amanita، Galerina، Gyromitra، Lepiota؛ ممکن است به‌اشتباه گاستروانتریت ویروسی یا مسمومیت غذایی تشخیص داده شود","جدول 128-1: GI زودرس (< 2 ساعت): Chlorophyllum molybdites، Omphalotus illudens، Cantharellus cibarius: تهوع، استفراغ، اسهال (گاه خونی)؛ GI 6 تا 24 ساعت (تأخیری): A. smithiana (نارسایی کلیه تأخیری)، A. phalloides/verna/virosa، Lepiota (نارسایی کبد تأخیری): اولیه تهوع/استفراغ/اسهال، روز 2: افزایش AST/ALT، روز 3: نارسایی کبد، کوآگولوپاتی، نارسایی کلیه با همولیز؛ Gyromitra esculenta: همان + سردرد، لرزش، آتاکسی، تشنج","موسکارینی (SLUDGE) (< 30 دقیقه): Inocybe، Clitocybe: سالیواسیون، اشک‌ریزش، اسهال، ترشحات GI؛ تحریک CNS (< 30 دقیقه): Amanita muscaria/pantherina/gemmata: مستی، سرگیجه، آتاکسی، اختلال بینایی، تشنج، تاکی‌کاردی، هیپرتانسیون، پوست گرم خشک، خشکی دهان، میدریاز (آنتی‌کولینرژیک)؛ توهم (< 30 دقیقه): Paneolus، Psilocybe، Gymnopillus: توهم بینایی و آتاکسی؛ شبه‌disulfiram: Coprinus atramentarius و Clitocybe clavipes (2 تا 72 ساعت بعد از قارچ و < 30 دقیقه بعد الکل): سردرد، flushing، تاکی‌کاردی، هیپرونتیلاسیون، تپش"],"ddx":[{"n":"Viral gastroenteritis / food poisoning |","cm":1},{"n":"Acute liver failure of other cause (APAP, viral hepatitis) |","cm":1},{"n":"Other toxic ingestion (plants, organophosphate) |"}],"redflags":["شروع تأخیری استفراغ/اسهال (> 6 ساعت)، افزایش آنزیم کبد، کوآگولوپاتی، آنسفالوپاتی، نارسایی کلیه"],"guide":"مشاوره با مرکز سموم (تفاوت منطقه‌ای). درمان طبق جدول 128-1. GI زودرس: هیدراتاسیون IV و ضداستفراغ. تأخیری (Amanita/Lepiota): هیدراتاسیون IV؛ پایش دقیق الکترولیت، گلوکز، کلیه، کبد و انعقاد؛ acetylcysteine بار 140 mg/kg PO/NG؛ penicillin G 300,000 تا 1,000,000 U/kg/روز IV؛ silymarin 5 mg/kg IV طی 1 ساعت سپس 20 mg/kg/روز IV (خوراکی در آمریکا). Gyromitra: همان + تشنج با بنزودیازپین و pyridoxine 5 g IV. موسکارینی: حمایتی؛ atropine 0.01 mg/kg IV در دیسترس شدید با تکرار؛ تحریک CNS: حمایتی و آرام‌بخشی با diazepam 2 تا 5 mg IV بزرگسال؛ توهم: حمایتی و diazepam؛ disulfiram-like: حمایتی و هیدراتاسیون IV. بستری همه با شروع تأخیری استفراغ/اسهال برای 48 ساعت پایش کلیه، کبد و مایع. پیشرفت سریع به انسفالوپاتی کبدی، سندرم هپاتورنال یا کوآگولوپاتی: اندیکاسیون پیوند؛ انتقال زودهنگام به مرکز پیوند. هالوسینوژن یا فقط موسکارینی: ترخیص پس از فروکش علائم.","section":"environmental","source":"Tintinalli's Emergency Medicine Manual, 8th ed., Ch. 128: Mushroom and Plant Poisoning, pp. 695–700"},"plant-poisoning-severe":{"id":"plant-poisoning-severe","variants":[{"id":"plant-severe-main","o":{"L":[{"t":"Electrolytes (potassium), BUN, creatinine, glucose; digoxin level (cross-reacts with cardiac glycoside plants); liver enzymes"}],"S":[{"t":"Digoxin-specific Fab antibody for dysrhythmias (foxglove, oleander)"},{"t":"Antidysrhythmics as needed"}],"T":[{"t":"Cardiac glycoside plants (foxglove, oleander) and hemlock / yew: GI decontamination with activated charcoal; monitor potassium"},{"t":"Castor bean / jequirity bean: whole-bowel irrigation; supportive care; yew: consider whole-bowel irrigation"},{"t":"Benzodiazepines for seizures (hemlock, water hemlock); supportive care"}],"Co":[{"t":"Admit if symptomatic; poison center; discharge after short observation if asymptomatic"}]},"name":"Severely poisonous plant ingestion (agent-specific)","level":"II","imp":"Severe plant poisoning","cond":"Urgent","act":"CBR","diet":"NPO","ecg":"stat","cxr":"none","sc":"کودک ۳ ساله پس از جویدن برگ خرزهره با استفراغ، برادیکاردی و PVC؛ یا بزرگسال پس از خوردن دانه کرچک.","why":"زغال برای گلیکوزید، WBI برای ریسین/abrus و Fab برای دیسریتمی."}],"ch":"128","name":"Severely poisonous plant ingestion (castor bean, jequirity, oleander, foxglove, hemlock, yew, coyotillo)","name_fa":"مسمومیت شدید با گیاه (کرچک، jequirity، خرزهره، انگشتانه، شوکران، سرخدار)","cc":["poisoning","nausea-vomiting","altered-mental-status"],"keywords":"castor bean, ricin, jequirity bean, abrin, oleander, foxglove, poison hemlock, water hemlock, yew, Taxus, coyotillo, خرزهره, کرچک, شوکران","status":"draft","features":["جدول 128-2: castor bean (Ricinus) و jequirity (Abrus): گاستروانتریت تأخیری، دلیریوم، تشنج، کما، مرگ؛ coyotillo (Karwinskia): فلج صعودی؛ foxglove (Digitalis) و oleander (Nerium): تهوع، استفراغ، اسهال، درد شکم، گیجی و دیسریتمی قلبی (مانند مسمومیت دیگوکسین)؛ poison hemlock (Conium): تاکی‌کاردی، لرزش، تعریق، میدریاز، ضعف عضلانی، تشنج، بلوک عصبی-عضلانی؛ water hemlock (Cicuta): تهوع، استفراغ، درد شکم، دلیریوم، تشنج، مرگ؛ yew (Taxus): شایع: تهوع، استفراغ، درد شکم؛ نادر: تشنج، دیسریتمی قلبی و کما","بیشتر مواجهه‌های گیاهی درمان نمی‌خواهند و پس از مشاهده کوتاه ترخیص"],"ddx":[{"n":"Digoxin toxicity (foxglove / oleander) |","cm":1},{"n":"Cholinergic / seizure of other cause |","cm":1},{"n":"Gastroenteritis |"}],"redflags":["دیسریتمی، تشنج، فلج، کما، گاستروانتریت تأخیری"],"guide":"castor bean/jequirity: WBI و حمایتی؛ coyotillo: حمایتی؛ foxglove/oleander: دکونتامیناسیون با زغال فعال، پایش پتاسیم، آنتی‌دیسریتمیک و digoxin-specific Fab برای دیسریتمی؛ poison hemlock: زغال و حمایتی؛ water hemlock: دکونتامیناسیون GI و حمایتی؛ yew: زغال فعال و در نظر گرفتن WBI، حمایتی.","section":"environmental","source":"Tintinalli's Emergency Medicine Manual, 8th ed., Ch. 128: Mushroom and Plant Poisoning, pp. 695–700"},"plant-poisoning-common":{"id":"plant-poisoning-common","variants":[{"id":"plant-common-main","o":{"T":[{"t":"Oral irritants (Dieffenbachia, philodendron, pothos): cold milk or ice cream, analgesics, consider steroids if severe"},{"t":"Toxicodendron dermatitis: skin protection, antipruritic and topical therapies; systemic steroids for facial, genital or widespread involvement"},{"t":"Activated charcoal GI decontamination for toxic ingestions as appropriate (e.g., nightshade, azalea, holly); supportive care"}],"Co":[{"t":"Discharge after short observation if no significant symptoms"}]},"name":"Common plant ingestion / contact","level":"III","imp":"Plant ingestion / exposure","cond":"Urgent","act":"CBR","diet":"PO","ecg":"once","cxr":"none","sc":"کودک ۲ ساله پس از جویدن برگ dumbcane با سوزش دهان و آب‌ریزش؛ یا بزرگسال با درماتیت خطی پس از تماس با پیچک سمی.","why":"بیشتر نیاز به درمان ندارند؛ مشاهده کوتاه و علامتی."},{"id":"plant-anticholinergic-cardiac","o":{"L":[{"t":"Electrolytes (potassium), glucose, BUN, creatinine; CK if agitated"}],"S":[{"t":"Digoxin-specific Fab antibody for arrhythmias from lily of the valley"},{"t":"Fluids or vasopressors for hypotension (azalea); atropine for symptomatic bradycardia (azalea)"}],"T":[{"t":"Activated charcoal GI decontamination; monitor potassium; antiarrhythmics (cardiac glycoside plants)"},{"t":"Anticholinergic plants: supportive care, benzodiazepines for agitation / seizures; consider physostigmine in severe cases"}],"Co":[{"t":"Admit if cardiac toxicity or severe anticholinergic syndrome; poison center"}]},"name":"Anticholinergic plant (Datura / belladonna) or cardiotoxic plant (lily of the valley, monkshood, azalea)","level":"II","imp":"Plant poisoning, anticholinergic / cardiotoxic","cond":"Urgent","act":"CBR","diet":"NPO","ecg":"stat","cxr":"none","sc":"نوجوانی پس از خوردن بذر Datura با توهم، میدریاز، تاکی‌کاردی، پوست گرم و خشک و آژیتاسیون.","why":"حمایتی و بنزودیازپین؛ physostigmine شدید؛ مانیتور قلب."}],"ch":"128","name":"Common plant ingestions and exposures (anticholinergic plants, oral irritants, dermatitis, others)","name_fa":"مسمومیت‌ها و تماس‌های شایع گیاهی","cc":["poisoning","rash","ent"],"keywords":"jimsonweed, Datura, nightshade, dieffenbachia, philodendron, poison ivy, Toxicodendron, aconite, monkshood, fava beans, ackee, colchicum, pokeweed, cactus, lantana, لولوی, دم گاو, پیچک سمی","status":"draft","features":["جدول 128-3: ackee: هیپوگلیسمی؛ aloe: درد شکم، اسهال، ادرار قرمز، نفریت؛ azalea (Rhododendron): معمولاً خفیف؛ شدید: سالیواسیون، اشک‌ریزش، برادیکاردی، هیپوتانسیون، فلج پیشرونده؛ cactus: خار فرورفته؛ Caladium، dumbcane (Dieffenbachia)، philodendron، pothos: معمولاً خفیف؛ شدید: سوزش و تحریک مخاط دهان، تورم، آب‌ریزش، دیسفاژی و اختلال تنفسی؛ Colchicum: گاستروانتریت دیررس و شدید ← نارسایی چندارگانی؛ fava beans (Vicia faba) در کمبود G6PD: اختلال GI، تب، سردرد، کم‌خونی همولیتیک، هموگلوبینوری، یرقان","آنتی‌کولینرژیک: henbane، jimsonweed (Datura)، deadly nightshade (Atropa belladonna): توهم، میدریاز، تاکی‌کاردی، آژیتاسیون، تشنج، کما؛ lily of the valley: مثل دیگوکسین؛ monkshood (Aconitum): برادیکاردی، بلوک قلبی، torsades، VF؛ nettle: سوزش موضعی؛ common/woody nightshade (Solanum) و سیب‌زمینی/بادمجان خام: تهوع، استفراغ، اسهال، درد شکم؛ دوز بالا: دلیریوم، توهم، کما؛ هسته هلو، زردآلو، گلابی، سیب وحشی، yam bean، hydrangea: سیانید حاد در مصرف زیاد: تعریق، تهوع، استفراغ، درد شکم، لتارژی؛ pepper (Capsicum): تحریک و درد تماسی؛ pokeweed: تحریک مخاط، درد شکم، استفراغ، اسهال شدید؛ شدید: کما و مرگ؛ yellow sage (Lantana): میدریاز، استفراغ، اسهال، ضعف، کما؛ Toxicodendron (پیچک، بلوط و sumac سمی): درماتیت؛ holly: گاستروانتریت (در مصرف قابل‌توجه می‌تواند کشنده باشد)؛ poinsettia: تحریک موضعی گاه؛ American mistletoe: گاستروانتریت؛ Easter lily: در انسان سمیت گزارش نشده"],"ddx":[{"n":"Anticholinergic toxidrome of other cause |","cm":1},{"n":"Allergic contact dermatitis |"},{"n":"Gastroenteritis |"}],"redflags":["دیسریتمی/بلوک قلبی (monkshood، lily of valley)، آنتی‌کولینرژیک شدید، اختلال تنفسی (تورم دهان)، هیپوگلیسمی (ackee)"],"guide":"ackee: گلوکز؛ aloe: حمایتی؛ azalea: زغال، atropine برای برادیکاردی علامت‌دار، مایع یا وازوپرسور برای هیپوتانسیون؛ cactus: برداشتن خار (rubber cement peel)؛ سوزش دهان (dumbcane، philodendron، pothos، Caladium): شیر یا بستنی سرد، مسکن، استروئید در علائم شدید؛ Colchicum: زغال، احیای مایع تهاجمی؛ fava: درمان بر اساس شدت همولیز؛ آنتی‌کولینرژیک گیاهی: حمایتی و physostigmine در موارد شدید؛ lily of the valley/monkshood: زغال، پایش K، آنتی‌آریتمیک، Fab؛ nettle: درمان علامتی؛ nightshade/potato: زغال و حمایتی؛ هسته‌ها (سیانید): زغال، WBI و آنتی‌دوت سیانید؛ pepper: شستشوی فراوان با آب؛ pokeweed: زغال و مایع؛ Toxicodendron: محافظت پوست، ضدخارش و موضعی، استروئید سیستمیک برای صورت، ژنیتال یا گسترده؛ holly، mistletoe، lantana: زغال و حمایتی؛ poinsettia: درمان لازم نیست؛ Easter lily: —.","section":"environmental","source":"Tintinalli's Emergency Medicine Manual, 8th ed., Ch. 128: Mushroom and Plant Poisoning, pp. 695–700"}});
